INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-oil-filter', 'part-oil-filter', 'Troca do Filtro de Óleo', 'Guia passo a passo para realizar a troca do filtro de óleo do Chevrolet Prisma 1.0 2009/2010.', 'easy', '30min', 30, NULL, '["Utilize luvas para evitar contato com óleo.","Limpe resíduos ao redor do filtro antes da instalação.","Descarte corretamente o filtro e óleo usados."]', '["Vazamento por aperto insuficiente ou excesso.","Filtro antigo grudado (necessário cuidado para retirar).","Rosca do bujão danificada."]', 'Procure um mecânico caso não tenha ferramentas ou se houver vazamento após instalação.', '2026-06-13T11:49:03.332+00:00', '2026-06-13T11:49:03.332+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-drain-plug', 'part-drain-plug', 'Troca do Vedador do Bujão do Cárter', 'Procedimento para substituir o vedador do bujão e eliminar vazamentos no cárter.', 'easy', '20min', 20, NULL, '["Utilize o vedador correto para o modelo do bujão.","Limpe completamente a região antes da remontagem."]', '["Rosca espanada no cárter.","Vazamento persistente por sujeira entre o vedador e o cárter."]', 'Procure um mecânico se a rosca do bujão estiver danificada ou se o vazamento persistir.', '2026-06-13T11:49:03.481+00:00', '2026-06-13T11:49:03.481+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket', 'part-oil-pan-gasket', 'Troca da Junta do Cárter', 'Procedimento para substituir a junta do cárter do Chevrolet Prisma 1.0 2009/2010 e eliminar vazamentos de óleo.', 'medium', '90min', 90, NULL, '["Trabalhe com o veículo bem apoiado e nivelado.","Limpe completamente as superfícies de vedação.","Descarte corretamente o óleo usado."]', '["Vazamento por limpeza incompleta da superfície.","Empenamento do cárter por aperto desigual.","Rosca de parafuso danificada."]', 'Procure um mecânico se o cárter estiver empenado ou se houver dificuldade no acesso aos parafusos.', '2026-06-13T11:49:03.601+00:00', '2026-06-13T11:49:03.601+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-engine-mounts', 'part-engine-mounts', 'Troca dos Coxins do Motor', 'Guia para substituir os coxins do motor do Chevrolet Prisma 1.0 2009/2010 e eliminar vibrações e trancos.', 'medium', '120min', 120, NULL, '["Sustente sempre o motor antes de soltar os coxins.","Substitua um coxim por vez.","Use o torque correto na fixação."]', '["Vibração persistente por coxim restante desgastado.","Ruído por desalinhamento do coxim.","Parafuso espanado na fixação."]', 'Procure um mecânico caso não tenha como sustentar o motor com segurança ou se as vibrações persistirem.', '2026-06-13T11:49:03.761+00:00', '2026-06-13T11:49:03.761+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-transmission-fluid', 'part-transmission-fluid', 'Troca do Fluido do Câmbio Manual', 'Procedimento para trocar o óleo da transmissão manual do Chevrolet Prisma 1.0 2009/2010.', 'easy', '30min', 30, NULL, '["Use a especificação correta 75W90 GL-4.","Mantenha o veículo nivelado.","Não complete com óleo de especificação diferente."]', '["Vazamento por bujão mal apertado.","Nível incorreto por veículo desnivelado.","Marchas ásperas se usado óleo errado."]', 'Procure um mecânico se o bujão estiver emperrado ou se houver dificuldade de acesso aos bujões.', '2026-06-13T11:49:03.920+00:00', '2026-06-13T11:49:03.920+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-air-filter', 'part-air-filter', 'Troca do Filtro de Ar', 'Procedimento simples para substituir o filtro de ar e garantir a entrada de ar limpo no motor.', 'easy', '15min', 15, NULL, '["Evite entrada de sujeira no duto de ar.","Utilize o filtro apropriado para o modelo do veículo."]', '["Filtro colocado em posição errada.","Não prender corretamente a caixa do filtro."]', 'Se estiver com dificuldade para identificar a peça, consulte um profissional.', '2026-06-13T11:49:04.081+00:00', '2026-06-13T11:49:04.081+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-throttle-body', 'part-throttle-body', 'Limpeza do Corpo de Borboleta', 'Procedimento para limpar o corpo de borboleta e corrigir marcha lenta irregular ou dificuldade de partida no Chevrolet Prisma 1.0.', 'medium', '45min', 45, NULL, '["Não utilize solventes agressivos que possam danificar as vedações internas.","Desconecte sempre a bateria antes da limpeza.","Evite contato de líquidos com o conector elétrico do sensor TPS."]', '["Marcha lenta instável após limpeza — normal por alguns minutos até o ECU adaptar.","Conector do TPS danificado durante remoção do duto.","Abraçadeiras mal posicionadas causando falsa aspiração de ar."]', 'Se a marcha lenta continuar irregular após a limpeza, o sensor TPS pode estar com defeito — procure um mecânico.', '2026-06-13T11:49:04.218+00:00', '2026-06-13T11:49:04.218+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-pcv-valve', 'part-pcv-valve', 'Limpeza e Troca da Válvula PCV', 'Procedimento para limpar ou substituir a válvula PCV do Chevrolet Prisma 1.0 2009/2010.', 'easy', '20min', 20, NULL, '["Trabalhe com o motor frio.","Verifique também o estado das mangueiras.","Use a válvula PCV correta para o motor 1.0."]', '["Marcha lenta irregular por entrada de ar falso.","Mangueira ressecada rompendo na remoção.","Válvula entupida que não resolve com limpeza."]', 'Procure um mecânico se a marcha lenta continuar irregular após a troca da válvula.', '2026-06-13T11:49:04.406+00:00', '2026-06-13T11:49:04.406+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-spark-plugs', 'part-spark-plugs', 'Troca das Velas de Ignição', 'Como substituir as velas de ignição para melhor desempenho e economia de combustível.', 'medium', '40min', 40, NULL, '["Verifique sempre as especificações do fabricante.","Trabalhe com o motor frio."]', '["Quebrar o cabo da vela ao puxar errado.","Rosca da vela espanada por excesso de torque."]', 'Procure um eletricista automotivo se a rosca da vela estiver danificada.', '2026-06-13T11:49:04.566+00:00', '2026-06-13T11:49:04.566+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-ignition-coils', 'part-ignition-coils', 'Substituição das Bobinas de Ignição', 'Guia para trocar as bobinas de ignição defeituosas que causam falhas no motor.', 'medium', '45min', 45, NULL, '["Desconecte sempre o cabo negativo da bateria antes de trabalhar.","Utilize bobinas compatíveis com o motor 1.0L 8V do Prisma."]', '["Mau contato no conector após montagem.","Bobina incompatível causando falha na ignição."]', 'Se houver falha recorrente após a troca, procure um eletricista automotivo para diagnóstico completo.', '2026-06-13T11:49:04.793+00:00', '2026-06-13T11:49:04.793+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-timing-belt', 'part-timing-belt', 'Troca da Correia Dentada', 'Procedimento completo para substituir a correia dentada, tensor e bomba d''água do motor 1.0L 8V Flexpower do Prisma.', 'hard', '180min', 180, NULL, '["A correia dentada é componente crítico de segurança — não economize com peças de procedência duvidosa.","Troque sempre o kit completo: correia + tensor + bomba d''água.","Respeite rigorosamente o intervalo de troca de 60.000km."]', '["Motor não parte após a troca por marcas de PMS fora de posição.","Barulho após a troca por tensão incorreta do tensor.","Vazamento de água por vedação incorreta da bomba d''água."]', 'A troca da correia dentada é serviço técnico avançado — se não tiver experiência, leve a um mecânico especializado.', '2026-06-13T11:49:04.955+00:00', '2026-06-13T11:49:04.955+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-clutch-cable', 'part-clutch-cable', 'Troca do Cabo de Embreagem', 'Passo a passo para substituir o cabo de embreagem com desgaste ou rompido no Chevrolet Prisma 1.0 com câmbio manual.', 'medium', '60min', 60, NULL, '["Não deixe o cabo novo com dobras acentuadas no trajeto.","Ajuste correto da folga é essencial — excesso causa patinamento, insuficiência causa desgaste prematuro."]', '["Dificuldade em engatar marcha após a troca — verificar regulagem da folga.","Cabo partindo novamente cedo — verificar canaleta danificada."]', 'Se houver dificuldade para engatar marchas mesmo após regulagem correta, o disco de embreagem pode estar desgastado.', '2026-06-13T11:49:05.149+00:00', '2026-06-13T11:49:05.149+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket', 'part-valve-cover-gasket', 'Troca da Junta da Tampa de Válvulas', 'Guia para substituir a junta da tampa de válvulas do Chevrolet Prisma 1.0 2009/2010 e eliminar vazamentos de óleo no cabeçote.', 'medium', '60min', 60, NULL, '["Trabalhe com o motor frio.","Limpe bem as superfícies de vedação.","Use o torque correto nos parafusos."]', '["Vazamento por aperto desigual.","Junta mal posicionada na canaleta.","Falha do motor por conexão de bobina solta."]', 'Procure um mecânico se o vazamento persistir ou se a tampa estiver empenada.', '2026-06-13T11:49:05.306+00:00', '2026-06-13T11:49:05.306+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-coolant', 'part-coolant', 'Troca do Líquido de Arrefecimento', 'Guia completo para trocar o fluido de arrefecimento do sistema do Prisma.', 'medium', '50min', 50, NULL, '["Não abra a tampa do radiador com o motor quente.","Descarte o líquido antigo corretamente."]', '["Vazamento após montagem incorreta das mangueiras.","Sistema com ar gera superaquecimento."]', 'Se houver bolhas recorrentes no reservatório, procure um especialista.', '2026-06-13T11:49:05.506+00:00', '2026-06-13T11:49:05.506+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-radiator', 'part-radiator', 'Substituição do Radiador', 'Guia para trocar o radiador danificado ou com vazamento no sistema de arrefecimento.', 'hard', '120min', 120, NULL, '["Desconecte a bateria antes de trabalhar na parte elétrica.","Nunca opere o motor sem o líquido de arrefecimento.","Descarte o líquido velho corretamente."]', '["Vazamento nas conexões das mangueiras.","Eletroventilador não reconectado corretamente."]', 'Este serviço exige conhecimento mecânico; se houver dúvida, procure oficina especializada.', '2026-06-13T11:49:05.703+00:00', '2026-06-13T11:49:05.703+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-thermostat', 'part-thermostat', 'Substituição do Termostato', 'Como trocar o termostato com defeito que compromete a regulação da temperatura do motor.', 'medium', '60min', 60, NULL, '["Nunca abra o sistema de arrefecimento com motor quente.","Descarte o líquido drenado corretamente.","Use termostato com temperatura de abertura correta (geralmente 88°C)."]', '["Termostato instalado invertido causando superaquecimento imediato.","Vazamento por junta mal posicionada."]', 'Se o motor continuar esquentando após a troca, verifique a bomba d''água e o radiador.', '2026-06-13T11:49:05.944+00:00', '2026-06-13T11:49:05.944+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-cooling-fan', 'part-cooling-fan', 'Substituição do Eletroventilador do Radiador', 'Como trocar o motor do ventilador do radiador caso ele apresente defeito.', 'medium', '60min', 60, NULL, '["Sempre desconecte a bateria antes de mexer no sistema elétrico.","Evite contato da hélice com as mãos."]', '["Plugue mal encaixado após montagem.","Protetor instalado fora de ordem pode interferir no arrefecimento."]', 'Procure auxílio se houver necessidade de desmontagem complexa.', '2026-06-13T11:49:06.158+00:00', '2026-06-13T11:49:06.158+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-water-pump', 'part-water-pump', 'Troca da Bomba D''água', 'Procedimento para substituir a bomba d''água do Chevrolet Prisma 1.0 2009/2010, realizado junto com a troca da correia dentada.', 'hard', '120min', 120, NULL, '["Sempre troque a correia dentada junto com a bomba.","Respeite as marcas de ponto do motor.","Faça a sangria do sistema de arrefecimento."]', '["Superaquecimento por ar no sistema.","Erro de ponto causando falha do motor.","Vazamento por junta da bomba mal assentada."]', 'Por envolver a correia dentada e o ponto do motor, recomenda-se forte a execução por um mecânico experiente.', '2026-06-13T11:49:06.379+00:00', '2026-06-13T11:49:06.379+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-radiator-hoses', 'part-radiator-hoses', 'Troca das Mangueiras do Radiador', 'Guia para substituir as mangueiras do radiador do Chevrolet Prisma 1.0 2009/2010.', 'easy', '40min', 40, NULL, '["Trabalhe sempre com o motor frio.","Substitua as abraçadeiras desgastadas.","Faça a sangria do sistema após o abastecimento."]', '["Vazamento por abraçadeira mal posicionada.","Superaquecimento por ar no sistema.","Bocal danificado ao remover mangueira ressecada."]', 'Procure um mecânico se um bocal estiver danificado ou se o vazamento persistir.', '2026-06-13T11:49:06.544+00:00', '2026-06-13T11:49:06.544+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-fuel-filter', 'part-fuel-filter', 'Substituição do Filtro de Combustível', 'Manual para trocar o filtro de combustível e restabelecer a vazão correta no sistema flex.', 'medium', '35min', 35, NULL, '["Nunca execute o serviço próximo a faíscas ou chamas.","Descarte corretamente o filtro contaminado com combustível."]', '["Vazamento por conexão mal encaixada.","Filtro montado no sentido invertido."]', 'Procure uma oficina se houver vazamento ou dificuldade para aliviar a pressão da linha.', '2026-06-13T11:49:06.712+00:00', '2026-06-13T11:49:06.712+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-fuel-pump', 'part-fuel-pump', 'Troca da Bomba de Combustível', 'Procedimento para substituir a bomba de combustível do Chevrolet Prisma 1.0 2009/2010, localizada dentro do tanque.', 'medium', '90min', 90, NULL, '["Trabalhe em local ventilado e sem chamas.","Despressurize o sistema antes de abrir.","Evite contaminação do tanque com sujeira."]', '["Vazamento de combustível por vedação mal feita.","Falha de partida por conexão elétrica solta.","Medidor de combustível impreciso por boia mal posicionada."]', 'Procure um mecânico se houver cheiro de combustível persistente ou dificuldade no acesso ao tanque.', '2026-06-13T11:49:06.852+00:00', '2026-06-13T11:49:06.852+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-fuel-injectors', 'part-fuel-injectors', 'Limpeza dos Injetores de Combustível', 'Procedimento para limpar os bicos injetores do Chevrolet Prisma 1.0 2009/2010 e restaurar a pulverização do combustível.', 'medium', '60min', 60, NULL, '["Trabalhe em local ventilado e sem chamas.","Substitua os anéis de vedação dos bicos.","Evite contaminar o coletor com sujeira."]', '["Vazamento por anel de vedação ressecado.","Marcha lenta irregular por injetor ainda obstruído.","Falha por chicote mal conectado."]', 'Procure um mecânico com máquina de ultrassom se os injetores estiverem muito entupidos ou com defeito.', '2026-06-13T11:49:07.036+00:00', '2026-06-13T11:49:07.036+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-lambda-sensor', 'part-lambda-sensor', 'Troca do Sensor Lambda/O2', 'Guia para substituir o sensor lambda (sonda de oxigênio) do Chevrolet Prisma 1.0 2009/2010.', 'medium', '45min', 45, NULL, '["Trabalhe com o escapamento frio.","Use graxa apropriada apenas na rosca.","Manuseie o sensor com cuidado, sem encostar na ponta."]', '["Rosca do escapamento danificada ao remover.","Luz de injeção persistente sem reset.","Consumo alto se instalado sensor incompatível."]', 'Procure um mecânico se a rosca estiver espanada ou se a luz de injeção não apagar após a troca.', '2026-06-13T11:49:07.160+00:00', '2026-06-13T11:49:07.160+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-wiper-blades', 'part-wiper-blades', 'Troca das Palhetas do Limpador de Para-brisa', 'Saiba como trocar as palhetas gastas para melhor visibilidade.', 'easy', '10min', 10, NULL, '["Não ligue o limpador sem palhetas.","Evite danificar o para-brisa ao manusear os braços."]', '["Palheta mal encaixada gera ruído ou não limpa direito.","Instalar tamanho errado prejudica eficiência."]', 'Caso o mecanismo do limpador apresente travamento, procure um profissional.', '2026-06-13T11:49:07.316+00:00', '2026-06-13T11:49:07.316+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-wiper-arms', 'part-wiper-arms', 'Substituição dos Braços do Limpador', 'Como trocar braços de limpador que estão tortos, com folga ou com regulagem incorreta.', 'easy', '20min', 20, NULL, '["Ao trabalhar sem palheta, cuidado para o braço não voltar e quebrar o vidro.","Verifique o ângulo de varredura antes de fixer definitivamente."]', '["Braço mal posicionado gerando falha na limpeza do para-brisa.","Porca de fixação afrouxando com o tempo."]', 'Se o eixo do limpador estiver com folga no para-brisa, pode ser necessário substituir o conjunto completo.', '2026-06-13T11:49:07.447+00:00', '2026-06-13T11:49:07.447+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-washer-fluid', 'part-washer-fluid', 'Reposição do Fluido do Limpador de Para-brisa', 'Procedimento simples para abastecer o reservatório do esguicho do limpador do Chevrolet Prisma 1.0 2009/2010.', 'easy', '5min', 5, NULL, '["Use apenas fluido específico para para-brisa.","Não confunda com outros reservatórios."]', '["Esguicho entupido por uso de produtos inadequados.","Bico desalinhado direcionando mal o jato."]', 'Procure ajuda se os esguichos não funcionarem mesmo com o reservatório cheio, pois pode haver falha na bomba do esguicho.', '2026-06-13T11:49:07.585+00:00', '2026-06-13T11:49:07.585+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-battery', 'part-battery', 'Substituição da Bateria', 'Guia para trocar a bateria descarregada/defeituosa com segurança.', 'easy', '20min', 20, NULL, '["Evite contato com ácido da bateria.","Não use anéis ou relógios durante a troca."]', '["Inversão dos cabos pode danificar o sistema.","Terminais afrouxados podem causar mau contato."]', 'Em caso de dúvida ou falha elétrica, procure um eletricista automotivo.', '2026-06-13T11:49:07.697+00:00', '2026-06-13T11:49:07.697+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-fuse-box', 'part-fuse-box', 'Substituição da Caixa de Fusíveis', 'Guia para trocar a caixa de fusíveis com defeito ou queimada que afeta múltiplos circuitos.', 'medium', '40min', 40, NULL, '["Desconecte a bateria antes de manipular a caixa de fusíveis.","Verifique se não há curto-circuito antes de instalar a caixa nova.","Mantenha cada fusível na posição correta conforme amperagem."]', '["Um ou mais circuitos não funcionam após a remontagem por conector mal encaixado.","Fusível de amperagem incorreta causando falha recorrente."]', 'Se múltiplos circuitos continuarem falhando após a troca, procure um eletricista automotivo.', '2026-06-13T11:49:07.854+00:00', '2026-06-13T11:49:07.854+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-fuses', 'part-fuses', 'Substituição dos Fusíveis', 'Como identificar e substituir fusíveis queimados na caixa de fusíveis do Prisma.', 'easy', '10min', 10, NULL, '["Sempre utilize fusíveis recomendados pelo manual.","Desligue o veículo antes de substituir. "]', '["Trocar fusível por amperagem errada pode causar danos.","Substituir repetidamente pode indicar problema elétrico mais grave."]', 'Se persistir o problema, consulte um eletricista automotivo para diagnóstico detalhado.', '2026-06-13T11:49:08.001+00:00', '2026-06-13T11:49:08.001+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-alternator', 'part-alternator', 'Troca do Alternador', 'Procedimento para substituir o alternador do Chevrolet Prisma 1.0 2009/2010.', 'hard', '120min', 120, NULL, '["Desconecte a bateria antes do serviço.","Identifique os cabos elétricos antes de soltar.","Confira o alinhamento e a tensão da correia."]', '["Luz da bateria acesa por cabo mal conectado.","Ruído por correia mal tensionada.","Carga insuficiente se o alternador for incompatível."]', 'Procure um mecânico se a tensão de carga estiver fora da faixa ou se houver dificuldade no acesso ao alternador.', '2026-06-13T11:49:08.130+00:00', '2026-06-13T11:49:08.130+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-starter-motor', 'part-starter-motor', 'Troca do Motor de Partida', 'Procedimento para substituir o motor de partida (arranque) do Chevrolet Prisma 1.0 2009/2010.', 'hard', '120min', 120, NULL, '["Desconecte a bateria antes do serviço.","Apoie o veículo com segurança.","Aperte firmemente os cabos do solenoide."]', '["Cliques na partida por cabo positivo mal apertado.","Ruído metálico por mau engrenamento.","Acesso difícil em alguns parafusos."]', 'Procure um mecânico se o acesso for muito restrito ou se o motor não acionar corretamente após a troca.', '2026-06-13T11:49:08.287+00:00', '2026-06-13T11:49:08.287+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-headlight-bulb', 'part-headlight-bulb', 'Substituição da Lâmpada do Farol', 'Passos para trocar a lâmpada queimada do farol dianteiro.', 'easy', '20min', 20, NULL, '["Desconecte a bateria para mais segurança.","Utilize sempre lâmpadas com especificação correta."]', '["Mau contato por montagem inadequada.","Danificar o soquete por força excessiva."]', 'Se o farol continuar não funcionando, procure um autoelétrico.', '2026-06-13T11:49:08.473+00:00', '2026-06-13T11:49:08.473+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-tail-light-bulb', 'part-tail-light-bulb', 'Substituição da Lâmpada da Lanterna Traseira', 'Manual para trocar a lâmpada da lanterna traseira e restaurar a iluminação de posição/freio.', 'easy', '20min', 20, NULL, '["Desligue a ignição antes da troca.","Evite tocar diretamente no vidro da lâmpada nova."]', '["Soquete com mau contato.","Oxidação no conector da lanterna."]', 'Se a luz continuar falhando após a troca, revise o chicote ou procure um autoelétrico.', '2026-06-13T11:49:08.623+00:00', '2026-06-13T11:49:08.623+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-turn-signal-bulb', 'part-turn-signal-bulb', 'Substituição da Lâmpada do Indicador de Direção', 'Passo a passo para trocar a lâmpada da seta dianteira ou traseira do Prisma.', 'easy', '20min', 20, NULL, '["Troque a lâmpada com o sistema desligado.","Utilize lâmpada âmbar compatível com o soquete."]', '["Pisca acelerado após instalação incorreta.","Oxidação no contato do soquete."]', 'Procure um profissional se o circuito continuar com falha após a troca da lâmpada.', '2026-06-13T11:49:08.757+00:00', '2026-06-13T11:49:08.757+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-reverse-light-bulb', 'part-reverse-light-bulb', 'Troca da Lâmpada de Ré', 'Procedimento simples para substituir a lâmpada de marcha à ré do Chevrolet Prisma 1.0 2009/2010.', 'easy', '15min', 15, NULL, '["Use a lâmpada da especificação correta.","Não toque o vidro da lâmpada com as mãos."]', '["Mau contato no soquete oxidado.","Lâmpada de potência errada.","Soquete mal recolocado."]', 'Procure um eletricista automotivo se a luz não acender mesmo com a lâmpada nova, pois pode ser falha no interruptor de ré.', '2026-06-13T11:49:08.877+00:00', '2026-06-13T11:49:08.877+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-license-plate-light', 'part-license-plate-light', 'Troca da Lâmpada da Placa', 'Procedimento simples para substituir a lâmpada de iluminação da placa traseira do Chevrolet Prisma 1.0 2009/2010.', 'easy', '10min', 10, NULL, '["Manuseie o plástico da luminária com cuidado.","Use a lâmpada torpedo correta."]', '["Trava da luminária quebrada.","Mau contato por oxidação.","Lâmpada de tamanho incompatível."]', 'Procure um eletricista automotivo se a luz não acender mesmo com a lâmpada nova.', '2026-06-13T11:49:08.981+00:00', '2026-06-13T11:49:08.981+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-front-brake-pads', 'part-front-brake-pads', 'Troca das Pastilhas de Freio Dianteiras', 'Guia detalhado para substituir as pastilhas de freio dianteiras do Prisma 1.0.', 'medium', '70min', 70, NULL, '["Sempre troque em pares (ambos os lados).","Fique atento ao torque dos parafusos."]', '["Ruído após montagem (pode indicar montagem errada).","Vazamento por má colocação da pinça."]', 'Caso sinta ruído ou pouca eficiência, procure um profissional imediatamente.', '2026-06-13T11:49:09.108+00:00', '2026-06-13T11:49:09.108+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-rear-brake-pads', 'part-rear-brake-pads', 'Troca das Pastilhas de Freio Traseiras', 'Procedimento para substituição das pastilhas traseiras com inspeção do conjunto de freio.', 'medium', '70min', 70, NULL, '["Sempre substitua as pastilhas do eixo em pares.","Verifique o nível do fluido após recuar o pistão."]', '["Pistão travado na pinça.","Desgaste irregular por pino-guia preso."]', 'Se houver travamento da pinça ou ruído persistente, leve o carro a uma oficina.', '2026-06-13T11:49:09.296+00:00', '2026-06-13T11:49:09.296+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-brake-fluid', 'part-brake-fluid', 'Substituição do Fluido de Freio', 'Manual para renovar o fluido DOT 4 e restaurar a resposta hidráulica do sistema de freio.', 'medium', '50min', 50, NULL, '["Use somente fluido novo e da especificação correta.","Não reutilize fluido removido do sistema."]', '["Entrada de ar no sistema por reservatório vazio.","Sangrador travado ou com vazamento."]', 'Procure assistência profissional se houver dificuldade para sangrar o sistema ou pedal baixo persistente.', '2026-06-13T11:49:09.435+00:00', '2026-06-13T11:49:09.435+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-front-brake-disc', 'part-front-brake-disc', 'Troca do Disco de Freio Dianteiro', 'Procedimento para substituir os discos de freio dianteiros do Chevrolet Prisma 1.0 2009/2010.', 'medium', '90min', 90, NULL, '["Apoie o veículo com segurança.","Troque os discos e pastilhas aos pares.","Bombeie o pedal antes de rodar."]', '["Vibração por disco empenado ou mal assentado.","Ruído por película protetora não removida.","Pedal baixo por não bombear antes de rodar."]', 'Procure um mecânico se houver vibração persistente na frenagem ou ruído anormal após a troca.', '2026-06-13T11:49:09.590+00:00', '2026-06-13T11:49:09.590+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-rear-brake-drum', 'part-rear-brake-drum', 'Troca do Tambor de Freio Traseiro', 'Procedimento para substituir os tambores de freio traseiros do Chevrolet Prisma 1.0 2009/2010.', 'medium', '90min', 90, NULL, '["Apoie o veículo com segurança.","Não respire a poeira das lonas.","Ajuste corretamente o regulador das lonas."]', '["Ruído por regulagem incorreta das lonas.","Frenagem fraca por lonas desgastadas.","Vazamento do cilindro de roda."]', 'Procure um mecânico se o cilindro de roda estiver vazando ou se a frenagem traseira continuar ineficiente.', '2026-06-13T11:49:09.763+00:00', '2026-06-13T11:49:09.763+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-handbrake', 'part-handbrake-cable', 'Ajuste do Cabo do Freio de Mão', 'Procedimento para ajustar o cabo do freio de estacionamento do Chevrolet Prisma 1.0 2009/2010.', 'easy', '30min', 30, NULL, '["Apoie o veículo com segurança.","Ajuste o cabo de forma gradual.","Confira se as lonas não arrastam após o ajuste."]', '["Freio de mão fraco por cabo esticado.","Lonas arrastando por excesso de tensão.","Cabo enferrujado que precisa de troca."]', 'Procure um mecânico se o cabo estiver enferrujado, rompido ou se o ajuste não resolver.', '2026-06-13T11:49:09.990+00:00', '2026-06-13T11:49:09.990+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-shock-absorbers', 'part-shock-absorbers', 'Substituição dos Amortecedores', 'Guia para troca dos amortecedores do Prisma com inspeção do conjunto da suspensão.', 'hard', '120min', 120, NULL, '["Troque amortecedores em pares por eixo.","Use compressor de mola adequado quando necessário."]', '["Ruído por aperto incorreto das fixações.","Geometria fora de ajuste após a troca."]', 'Esse serviço exige ferramenta e procedimento corretos; se houver dúvida, procure oficina especializada.', '2026-06-13T11:49:10.155+00:00', '2026-06-13T11:49:10.155+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-ball-joints', 'part-ball-joints', 'Substituição das Articulações da Suspensão', 'Passo a passo para trocar pivôs e articulações com folga na suspensão do Prisma.', 'hard', '90min', 90, NULL, '["Sempre revise os demais componentes da suspensão no mesmo serviço.","Faça alinhamento após a substituição."]', '["Folga residual por montagem incorreta.","Parafusos antigos sem torque adequado."]', 'Se houver dificuldade na extração ou montagem, leve o carro a uma oficina de suspensão.', '2026-06-13T11:49:10.296+00:00', '2026-06-13T11:49:10.296+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-cv-boot', 'part-cv-boot', 'Verificação e Troca das Coifas do Homocinético', 'Como inspecionar e substituir as coifas de borracha do homocinético para evitar danos ao semi-eixo do Prisma 1.0.', 'easy', '30min', 30, NULL, '["Coifa rasgada sem correção rápida pode inutilizar o homocinético inteiro.","Não use graxa diferente da específica para homocinético."]', '["Graxa insuficiente causando desgaste acelerado do homocinético.","Abraçadeira mal fixada causando fuga de graxa.","Homocinético já danificado quando a coifa foi encontrada rasgada."]', 'Se ouvir clique nas curvas após a troca da coifa, o homocinético precisará de substituição completa.', '2026-06-13T11:49:10.424+00:00', '2026-06-13T11:49:10.424+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-power-steering-fluid', 'part-power-steering-fluid', 'Troca do Fluido da Direção Hidráulica', 'Procedimento para substituir o fluido da direção hidráulica e manter o sistema de direção assistida do Prisma em bom funcionamento.', 'easy', '30min', 30, NULL, '["Nível baixo de fluido pode danificar a bomba de direção.","Use apenas fluido específico para direção hidráulica — nunca ATF ou óleo de motor."]', '["Volante ainda pesado após a troca — pode indicar desgaste na bomba.","Nível caindo rapidamente — verifique vazamentos nas mangueiras."]', 'Se o volante continuar pesado mesmo com fluido correto, a bomba da direção pode precisar de substituição.', '2026-06-13T11:49:10.559+00:00', '2026-06-13T11:49:10.559+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-tie-rods', 'part-tie-rods', 'Troca dos Terminais de Direção', 'Procedimento para substituir os terminais de direção do Chevrolet Prisma 1.0 2009/2010.', 'medium', '60min', 60, NULL, '["Apoie o veículo com segurança.","Conte as voltas para manter o alinhamento aproximado.","Faça o alinhamento após a troca."]', '["Desgaste irregular dos pneus por falta de alinhamento.","Folga persistente se a barra axial também estiver gasta.","Coifa rasgada permitindo entrada de sujeira."]', 'Após a troca, procure sempre um serviço de alinhamento e balanceamento profissional.', '2026-06-13T11:49:10.705+00:00', '2026-06-13T11:49:10.705+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-stabilizer-bushings', 'part-stabilizer-bushings', 'Troca das Buchas da Barra Estabilizadora', 'Procedimento para substituir as buchas da barra estabilizadora do Chevrolet Prisma 1.0 2009/2010.', 'easy', '45min', 45, NULL, '["Apoie o veículo com segurança.","Use graxa compatível com borracha.","Aperte os suportes no torque correto."]', '["Ruído persistente se as bieletas também estiverem gastas.","Bucha mal posicionada gerando folga.","Parafusos do suporte espanados."]', 'Procure um mecânico se o ruído continuar após a troca, pois pode ser desgaste em outros componentes da suspensão.', '2026-06-13T11:49:10.883+00:00', '2026-06-13T11:49:10.883+00:00');
INSERT OR IGNORE INTO Guide (id, partId, title, description, difficulty, estimatedTime, estimatedTimeMinutes, imageUrl, precautions, commonIssues, professionalHelp, createdAt, updatedAt) VALUES ('guide-wheel-bearings', 'part-wheel-bearings', 'Troca dos Rolamentos de Roda', 'Procedimento para substituir os rolamentos de roda do Chevrolet Prisma 1.0 2009/2010.', 'hard', '120min', 120, NULL, '["Apoie o veículo com segurança.","Prense o rolamento apenas pela pista correta.","Respeite o torque da porca do cubo."]', '["Ruído persistente por instalação incorreta.","Folga por porca do cubo sub-apertada.","Dano ao rolamento por prensagem errada."]', 'Por exigir prensa e torque elevado, recomenda-se a execução por um mecânico equipado.', '2026-06-13T11:49:11.037+00:00', '2026-06-13T11:49:11.037+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-filter-step-1', 'guide-oil-filter', 1, 'Preparação do veículo', 'Estacione o veículo em superfície plana, desligue o motor e aguarde esfriar.', NULL, '["Levante o carro com macaco para facilitar acesso."]', '["Espere o motor esfriar para evitar queimaduras."]', '2026-06-13T11:49:03.356+00:00', '2026-06-13T11:49:03.356+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-filter-step-2', 'guide-oil-filter', 2, 'Drenagem do óleo', 'Remova o bujão do cárter com a chave soquete e deixe o óleo escorrer no recipiente.', NULL, '["Troque a arruela do bujão se necessário."]', '["Descarte o óleo usado corretamente."]', '2026-06-13T11:49:03.381+00:00', '2026-06-13T11:49:03.381+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-filter-step-3', 'guide-oil-filter', 3, 'Remoção do filtro antigo', 'Use a chave para soltar e remover o filtro de óleo antigo, tomando cuidado com resíduos.', NULL, '["Lubrifique o anel de vedação do novo filtro."]', '[]', '2026-06-13T11:49:03.402+00:00', '2026-06-13T11:49:03.402+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-filter-step-4', 'guide-oil-filter', 4, 'Instalação do novo filtro', 'Instale o filtro de óleo novo e aperte à mão até encostar bem.', NULL, '["Não aperte em excesso."]', '[]', '2026-06-13T11:49:03.421+00:00', '2026-06-13T11:49:03.421+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-filter-step-5', 'guide-oil-filter', 5, 'Abastecimento e conferência', 'Recoloque o bujão, adicione o óleo novo, ligue o motor e verifique vazamentos.', NULL, '["Verifique o nível do óleo após o motor esfriar."]', '["Não exceda o limite máximo de óleo."]', '2026-06-13T11:49:03.440+00:00', '2026-06-13T11:49:03.440+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-drain-plug-step-1', 'guide-drain-plug', 1, 'Preparação do veículo', 'Deixe o motor esfriar, eleve a dianteira com segurança e posicione o recipiente sob o cárter.', NULL, '["Aproveite para inspecionar sinais de vazamento ao redor do bujão."]', '["Nunca trabalhe com o veículo apoiado apenas no macaco."]', '2026-06-13T11:49:03.500+00:00', '2026-06-13T11:49:03.500+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-drain-plug-step-2', 'guide-drain-plug', 2, 'Remoção do bujão', 'Afrouxe o bujão do cárter e retire cuidadosamente o vedador antigo.', NULL, '["Guarde o bujão em local limpo para evitar contaminação."]', '["Pode haver saída de óleo residual mesmo fora do período de troca."]', '2026-06-13T11:49:03.520+00:00', '2026-06-13T11:49:03.520+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-drain-plug-step-3', 'guide-drain-plug', 3, 'Instalação do vedador novo', 'Limpe a área de contato, encaixe o vedador novo no bujão e rosqueie novamente no cárter.', NULL, '["Rosqueie manualmente antes do aperto final para não cruzar a rosca."]', '["Aperto excessivo pode danificar a rosca do cárter."]', '2026-06-13T11:49:03.541+00:00', '2026-06-13T11:49:03.541+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-drain-plug-step-4', 'guide-drain-plug', 4, 'Conferência final', 'Complete o nível de óleo se necessário, ligue o motor e verifique se o vazamento cessou.', NULL, '["Observe novamente após alguns minutos com o motor desligado."]', '[]', '2026-06-13T11:49:03.561+00:00', '2026-06-13T11:49:03.561+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket-step-1', 'guide-oil-pan-gasket', 1, 'Preparação e drenagem do óleo', 'Eleve a dianteira com segurança, posicione o recipiente sob o cárter e drene todo o óleo do motor.', NULL, '["Drene com o motor morno para o óleo escorrer melhor."]', '["Apoie o veículo em cavaletes, nunca apenas no macaco.","Aguarde o motor esfriar para evitar queimaduras."]', '2026-06-13T11:49:03.620+00:00', '2026-06-13T11:49:03.620+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket-step-2', 'guide-oil-pan-gasket', 2, 'Remoção do cárter', 'Solte todos os parafusos de fixação do cárter em sequência e retire a peça com cuidado.', NULL, '["Solte os parafusos em forma de cruz para aliviar a tensão uniformemente."]', '["Pode haver óleo residual ao remover o cárter."]', '2026-06-13T11:49:03.645+00:00', '2026-06-13T11:49:03.645+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket-step-3', 'guide-oil-pan-gasket', 3, 'Limpeza das superfícies', 'Remova totalmente os resíduos da junta antiga do cárter e do bloco com espátula plástica e limpa-peças.', NULL, '["Use espátula plástica para não riscar as superfícies de vedação."]', '["Não deixe resíduos da junta antiga, pois causam vazamento."]', '2026-06-13T11:49:03.664+00:00', '2026-06-13T11:49:03.664+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket-step-4', 'guide-oil-pan-gasket', 4, 'Instalação da junta nova', 'Posicione a junta nova, recoloque o cárter e aperte os parafusos com torquímetro na sequência correta.', NULL, '["Aperte os parafusos de forma cruzada e gradual."]', '["Respeite o torque especificado para não deformar o cárter."]', '2026-06-13T11:49:03.687+00:00', '2026-06-13T11:49:03.687+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-oil-pan-gasket-step-5', 'guide-oil-pan-gasket', 5, 'Abastecimento e teste', 'Abasteça com óleo novo, ligue o motor e verifique se há vazamentos na junta do cárter.', NULL, '["Confira o nível do óleo após o motor esfriar."]', '["Observe a região da junta por alguns minutos com o motor ligado."]', '2026-06-13T11:49:03.717+00:00', '2026-06-13T11:49:03.717+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-engine-mounts-step-1', 'guide-engine-mounts', 1, 'Preparação e apoio do motor', 'Abra o capô e posicione um macaco com calço de madeira sob o cárter para sustentar o peso do motor.', NULL, '["Use um calço de madeira para não danificar o cárter."]', '["Sustente o motor antes de soltar qualquer coxim."]', '2026-06-13T11:49:03.783+00:00', '2026-06-13T11:49:03.783+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-engine-mounts-step-2', 'guide-engine-mounts', 2, 'Identificação dos coxins', 'Localize os coxins direito, esquerdo e o coxim do câmbio. Avalie qual está desgastado ou rompido.', NULL, '["Substitua um coxim de cada vez para manter o motor apoiado."]', '["Não solte todos os coxins ao mesmo tempo."]', '2026-06-13T11:49:03.804+00:00', '2026-06-13T11:49:03.804+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-engine-mounts-step-3', 'guide-engine-mounts', 3, 'Remoção do coxim antigo', 'Levante levemente o motor com o macaco, solte os parafusos do coxim e remova a peça desgastada.', NULL, '["Eleve o motor apenas o necessário para aliviar o coxim."]', '["Cuidado com mangueiras e cabos próximos ao coxim."]', '2026-06-13T11:49:03.827+00:00', '2026-06-13T11:49:03.827+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-engine-mounts-step-4', 'guide-engine-mounts', 4, 'Instalação do coxim novo', 'Posicione o coxim novo e aperte os parafusos com torquímetro no torque especificado.', NULL, '["Alinhe o coxim antes de apertar definitivamente."]', '["Respeite o torque para evitar folgas ou trincas."]', '2026-06-13T11:49:03.853+00:00', '2026-06-13T11:49:03.853+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-engine-mounts-step-5', 'guide-engine-mounts', 5, 'Teste e verificação', 'Abaixe o motor, retire o macaco, ligue o motor e verifique se as vibrações cessaram.', NULL, '["Acelere levemente para confirmar a estabilidade do motor."]', '["Confira se não há trancos ao engatar marchas."]', '2026-06-13T11:49:03.875+00:00', '2026-06-13T11:49:03.875+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-transmission-fluid-step-1', 'guide-transmission-fluid', 1, 'Preparação do veículo', 'Eleve o veículo nivelado e localize os bujões de enchimento e de dreno da caixa de câmbio.', NULL, '["Identifique o bujão de enchimento antes de drenar."]', '["Mantenha o veículo nivelado para a medição correta do nível."]', '2026-06-13T11:49:03.941+00:00', '2026-06-13T11:49:03.941+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-transmission-fluid-step-2', 'guide-transmission-fluid', 2, 'Drenagem do óleo antigo', 'Remova primeiro o bujão de enchimento, depois o de dreno, deixando o óleo escorrer no recipiente.', NULL, '["Abrir o bujão de enchimento primeiro garante que será possível reabastecer."]', '["O óleo pode estar morno e escorrer rapidamente."]', '2026-06-13T11:49:03.959+00:00', '2026-06-13T11:49:03.959+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-transmission-fluid-step-3', 'guide-transmission-fluid', 3, 'Abastecimento com óleo novo', 'Recoloque o bujão de dreno e abasteça pelo bujão de enchimento até o óleo transbordar levemente.', NULL, '["Use bomba manual para facilitar o abastecimento pelo lado da caixa."]', '["O nível correto é quando o óleo atinge a borda do furo de enchimento."]', '2026-06-13T11:49:03.981+00:00', '2026-06-13T11:49:03.981+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-transmission-fluid-step-4', 'guide-transmission-fluid', 4, 'Fechamento e verificação', 'Recoloque o bujão de enchimento, limpe a região e verifique se não há vazamentos.', NULL, '["Teste as marchas após a troca."]', '["Descarte o óleo usado corretamente."]', '2026-06-13T11:49:04.009+00:00', '2026-06-13T11:49:04.009+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-air-filter-step-1', 'guide-air-filter', 1, 'Abertura da caixa do filtro', 'Abra o capô e localize a caixa do filtro de ar. Solte as presilhas ou parafusos de fixação.', NULL, '["Tire fotos para referência."]', '[]', '2026-06-13T11:49:04.106+00:00', '2026-06-13T11:49:04.106+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-air-filter-step-2', 'guide-air-filter', 2, 'Remoção do filtro antigo', 'Retire o filtro de ar antigo, evitando que sujeiras caiam na entrada de ar.', NULL, '["Limpe a caixa com pano seco."]', '[]', '2026-06-13T11:49:04.127+00:00', '2026-06-13T11:49:04.127+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-air-filter-step-3', 'guide-air-filter', 3, 'Instalação do filtro novo', 'Coloque o novo filtro e certifique-se de que fique bem ajustado.', NULL, '["Verifique se o filtro está na posição correta."]', '[]', '2026-06-13T11:49:04.149+00:00', '2026-06-13T11:49:04.149+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-air-filter-step-4', 'guide-air-filter', 4, 'Fechamento e conferência', 'Feche a caixa do filtro e prenda todas as presilhas ou parafusos.', NULL, '[]', '["Certifique-se de que não haja folgas."]', '2026-06-13T11:49:04.174+00:00', '2026-06-13T11:49:04.174+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-throttle-body-step-1', 'guide-throttle-body', 1, 'Preparação', 'Desligue o motor, desconecte o cabo negativo da bateria e aguarde o motor esfriar completamente.', NULL, '["Fotografe os dutos antes de desmontar para facilitar a remontagem."]', '["Nunca limpe o corpo de borboleta com o motor ligado."]', '2026-06-13T11:49:04.240+00:00', '2026-06-13T11:49:04.240+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-throttle-body-step-2', 'guide-throttle-body', 2, 'Remoção do duto de admissão', 'Afrouxe as abraçadeiras e remova o duto flexível de borracha que conecta o filtro de ar ao corpo de borboleta.', NULL, '["Guarde as abraçadeiras em local seguro."]', '[]', '2026-06-13T11:49:04.263+00:00', '2026-06-13T11:49:04.263+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-throttle-body-step-3', 'guide-throttle-body', 3, 'Limpeza da borboleta', 'Aplique o limpa corpo de borboleta na borboleta aberta (abra manualmente com o dedo) e remova os depósitos de carbono com a escova e pano.', NULL, '["Limpe a sede da borboleta com movimentos circulares.","Abra a borboleta com os dedos para limpar a parte interna do canal."]', '["Não use produto abrasivo que possa arranhar o alumínio."]', '2026-06-13T11:49:04.285+00:00', '2026-06-13T11:49:04.285+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-throttle-body-step-4', 'guide-throttle-body', 4, 'Remontagem e resetagem do ECU', 'Reinstale o duto de admissão, reconecte a bateria e ligue o motor para o ECU recalibrar a posição de marcha lenta.', NULL, '["Após ligar, o carro pode apresentar marcha lenta irregular por alguns minutos até o ECU adaptar — isso é normal."]', '["Não acelere em excesso nos primeiros 5 minutos após a limpeza."]', '2026-06-13T11:49:04.311+00:00', '2026-06-13T11:49:04.311+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-throttle-body-step-5', 'guide-throttle-body', 5, 'Verificação da marcha lenta', 'Com o motor em temperatura normal, verifique se a marcha lenta estabiliza entre 750 e 850 RPM.', NULL, '["Se não estabilizar, desconecte a bateria por 10 minutos para resetar o ECU."]', '[]', '2026-06-13T11:49:04.332+00:00', '2026-06-13T11:49:04.332+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-pcv-valve-step-1', 'guide-pcv-valve', 1, 'Localização da válvula', 'Abra o capô e localize a válvula PCV na região da tampa de válvulas e mangueira de ventilação.', NULL, '["Consulte o manual para identificar a posição exata."]', '["Faça o serviço com o motor frio."]', '2026-06-13T11:49:04.429+00:00', '2026-06-13T11:49:04.429+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-pcv-valve-step-2', 'guide-pcv-valve', 2, 'Remoção da válvula', 'Solte a presilha da mangueira e retire a válvula PCV do encaixe.', NULL, '["Chacoalhe a válvula: se não chocalhar, está presa e deve ser trocada."]', '["Não force a mangueira ressecada para não rompê-la."]', '2026-06-13T11:49:04.453+00:00', '2026-06-13T11:49:04.453+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-pcv-valve-step-3', 'guide-pcv-valve', 3, 'Limpeza ou substituição', 'Limpe a válvula com limpa-carburador ou instale uma válvula nova caso esteja entupida.', NULL, '["Se a válvula estiver muito suja, prefira a troca."]', '["Deixe a válvula secar antes de reinstalar."]', '2026-06-13T11:49:04.479+00:00', '2026-06-13T11:49:04.479+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-pcv-valve-step-4', 'guide-pcv-valve', 4, 'Reinstalação e teste', 'Reinstale a válvula, prenda a mangueira e ligue o motor verificando a marcha lenta.', NULL, '["A marcha lenta deve estabilizar após a troca."]', '["Garanta que a mangueira esteja bem fixada para não entrar ar falso."]', '2026-06-13T11:49:04.502+00:00', '2026-06-13T11:49:04.502+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-spark-plugs-step-1', 'guide-spark-plugs', 1, 'Localização das velas', 'Com o motor frio, abra o capô e localize as velas de ignição.', NULL, '[]', '[]', '2026-06-13T11:49:04.626+00:00', '2026-06-13T11:49:04.626+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-spark-plugs-step-2', 'guide-spark-plugs', 2, 'Remoção dos cabos', 'Remova os cabos das velas puxando pela base, nunca pelo fio.', NULL, '["Marque a ordem dos cabos."]', '["Nunca force o cabo para evitar rupturas."]', '2026-06-13T11:49:04.648+00:00', '2026-06-13T11:49:04.648+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-spark-plugs-step-3', 'guide-spark-plugs', 3, 'Remoção das velas antigas', 'Use a chave de vela para remover as velas, girando no sentido anti-horário.', NULL, '["Verifique desgaste nas velas antigas."]', '[]', '2026-06-13T11:49:04.686+00:00', '2026-06-13T11:49:04.686+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-spark-plugs-step-4', 'guide-spark-plugs', 4, 'Instalação das novas velas', 'Aplique lubrificante na rosca, instale as novas velas com a mão e depois dê o torque final com a chave.', NULL, '["Não aperte em excesso para evitar danificar a rosca."]', '[]', '2026-06-13T11:49:04.708+00:00', '2026-06-13T11:49:04.708+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-spark-plugs-step-5', 'guide-spark-plugs', 5, 'Reinstalação dos cabos', 'Coloque os cabos novamente, respeitando a ordem.', NULL, '["Ouça o clique de encaixe."]', '[]', '2026-06-13T11:49:04.745+00:00', '2026-06-13T11:49:04.745+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ignition-coils-step-1', 'guide-ignition-coils', 1, 'Desconexão da bateria', 'Desligue o cabo negativo da bateria para evitar curto-circuito.', NULL, '["Aguarde alguns minutos antes de trabalhar no sistema de ignição."]', '["Nunca trabalhe no sistema de ignição com a bateria conectada."]', '2026-06-13T11:49:04.813+00:00', '2026-06-13T11:49:04.813+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ignition-coils-step-2', 'guide-ignition-coils', 2, 'Localização das bobinas', 'Abra o capô e localize as 4 bobinas de ignição sobre o cabeçote, próximas às velas.', NULL, '["Fotografe a posição dos conectores antes de desconectar."]', '[]', '2026-06-13T11:49:04.835+00:00', '2026-06-13T11:49:04.835+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ignition-coils-step-3', 'guide-ignition-coils', 3, 'Remoção das bobinas', 'Desconecte o conector elétrico de cada bobina e retire os parafusos de fixação com chave 10mm.', NULL, '["Trabalhe em uma bobina por vez para não misturar a ordem."]', '[]', '2026-06-13T11:49:04.858+00:00', '2026-06-13T11:49:04.858+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ignition-coils-step-4', 'guide-ignition-coils', 4, 'Instalação das novas bobinas', 'Posicione a bobina nova, recoloque os parafusos e reconecte o chicote elétrico.', NULL, '["Verifique se a bobina está bem assentada antes de apertar."]', '["Não force os conectores para não danificar o soquete."]', '2026-06-13T11:49:04.882+00:00', '2026-06-13T11:49:04.882+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ignition-coils-step-5', 'guide-ignition-coils', 5, 'Teste e verificação', 'Conecte a bateria, ligue o motor e observe se a luz de injeção apaga. Faça teste de aceleração.', NULL, '["Se a luz de falha persistir, verifique as bobinas com multímetro."]', '[]', '2026-06-13T11:49:04.904+00:00', '2026-06-13T11:49:04.904+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-timing-belt-step-1', 'guide-timing-belt', 1, 'Preparação e acesso', 'Eleve o veículo com segurança. Remova a roda dianteira direita e a proteção inferior do motor para acessar a cobertura da correia.', NULL, '["Marque a posição das polias com tinta ou caneta marcadora antes de remover a correia."]', '["Apoie o veículo em cavaletes — nunca trabalhe apenas com o macaco hidráulico."]', '2026-06-13T11:49:04.980+00:00', '2026-06-13T11:49:04.980+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-timing-belt-step-2', 'guide-timing-belt', 2, 'Alinhamento no PMS', 'Gire manualmente o motor pela polia do virabrequim até o cilindro 1 atingir o Ponto Morto Superior (PMS). Confirme com as marcas de referência no bloco e no cabeçote.', NULL, '["Nunca gire o motor pela polia do eixo comando — sempre pelo virabrequim."]', '["Com a correia removida, não gire o eixo comando ou virabrequim separadamente para evitar contato de válvulas com pistões."]', '2026-06-13T11:49:05.001+00:00', '2026-06-13T11:49:05.001+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-timing-belt-step-3', 'guide-timing-belt', 3, 'Remoção da correia antiga', 'Remova a cobertura da correia dentada, afrouxe o tensor e retire a correia. Substitua também o tensor e a bomba d''água enquanto o conjunto está aberto.', NULL, '["Aproveite para inspecionar o estado dos retentores das polias."]', '["Descarte a correia usada — nunca reutilize uma correia dentada."]', '2026-06-13T11:49:05.024+00:00', '2026-06-13T11:49:05.024+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-timing-belt-step-4', 'guide-timing-belt', 4, 'Instalação da correia nova', 'Monte o tensor novo, instale a correia nova seguindo a ordem: virabrequim → bomba d''água → tensionador → polia do eixo comando. Ajuste a tensão conforme especificação.', NULL, '["Verifique se as marcas de alinhamento estão corretas antes de tensionar."]', '["Aperto incorreto do tensor compromete a vida útil da correia."]', '2026-06-13T11:49:05.061+00:00', '2026-06-13T11:49:05.061+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-timing-belt-step-5', 'guide-timing-belt', 5, 'Verificação e fechamento', 'Gire o motor manualmente 2 voltas completas e verifique se as marcas de PMS ainda estão alinhadas. Reinstale a cobertura, a roda e a proteção inferior.', NULL, '["Complete o fluido de arrefecimento se a bomba d''água foi substituída."]', '["Antes de ligar o motor, sempre confirme o alinhamento das marcas de referência."]', '2026-06-13T11:49:05.100+00:00', '2026-06-13T11:49:05.100+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-clutch-cable-step-1', 'guide-clutch-cable', 1, 'Verificação da regulagem atual', 'Localize o pedal de embreagem e a porca de regulagem na extremidade do cabo. Anote ou fotografe a posição atual da regulagem.', NULL, '["A folga correta do pedal é de 15 a 25mm antes de sentir resistência."]', '[]', '2026-06-13T11:49:05.179+00:00', '2026-06-13T11:49:05.179+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-clutch-cable-step-2', 'guide-clutch-cable', 2, 'Remoção do cabo antigo', 'Afrouxe a porca de regulagem do lado do câmbio e desencaixe o cabo do garfo. No pedal, desencaixe o terminal do cabo do pino do pedal.', NULL, '["Puxe o cabo com cuidado para não danificar a canaleta de passagem."]', '["Verifique sinais de desgaste na canaleta — se danificada, troque também."]', '2026-06-13T11:49:05.203+00:00', '2026-06-13T11:49:05.203+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-clutch-cable-step-3', 'guide-clutch-cable', 3, 'Instalação do cabo novo', 'Passe o cabo novo pelo mesmo trajeto do antigo. Aplique graxa nas pontas e encaixe primeiro no garfo do câmbio, depois no pedal.', NULL, '["Graxa nas pontas aumenta a vida útil e torna o acionamento mais suave."]', '["Confirme que o cabo passou corretamente pela canaleta sem dobras bruscas."]', '2026-06-13T11:49:05.225+00:00', '2026-06-13T11:49:05.225+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-clutch-cable-step-4', 'guide-clutch-cable', 4, 'Regulagem da folga', 'Ajuste a porca de regulagem até obter 15-25mm de folga no pedal antes de sentir resistência. Confirme que as marchas engajam suavemente.', NULL, '["Faça o teste com o motor desligado antes e depois com motor ligado."]', '["Folga insuficiente mantém a embreagem parcialmente acionada, causando desgaste prematuro."]', '2026-06-13T11:49:05.246+00:00', '2026-06-13T11:49:05.246+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-clutch-cable-step-5', 'guide-clutch-cable', 5, 'Teste em movimento', 'Faça percurso curto em local seguro testando o acionamento da embreagem e o engajamento de todas as marchas.', NULL, '["Faça nova verificação da folga após o primeiro percurso — o cabo novo pode acomodar ligeiramente."]', '[]', '2026-06-13T11:49:05.266+00:00', '2026-06-13T11:49:05.266+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket-step-1', 'guide-valve-cover-gasket', 1, 'Remoção dos componentes superiores', 'Desconecte as bobinas, cabos e mangueiras que ficam sobre a tampa de válvulas.', NULL, '["Fotografe as conexões antes de desconectar."]', '["Trabalhe com o motor frio."]', '2026-06-13T11:49:05.331+00:00', '2026-06-13T11:49:05.331+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket-step-2', 'guide-valve-cover-gasket', 2, 'Remoção da tampa de válvulas', 'Solte os parafusos da tampa em sequência e retire a tampa com cuidado.', NULL, '["Solte os parafusos de forma cruzada."]', '["Não force a tampa para não empená-la."]', '2026-06-13T11:49:05.351+00:00', '2026-06-13T11:49:05.351+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket-step-3', 'guide-valve-cover-gasket', 3, 'Limpeza das superfícies', 'Remova a junta antiga e limpe a canaleta da tampa e a superfície do cabeçote.', NULL, '["Use espátula plástica para não riscar a superfície."]', '["Não deixe resíduos da junta nem sujeira cair no motor."]', '2026-06-13T11:49:05.386+00:00', '2026-06-13T11:49:05.386+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket-step-4', 'guide-valve-cover-gasket', 4, 'Instalação da junta nova', 'Encaixe a junta nova na canaleta, recoloque a tampa e aperte os parafusos com torquímetro.', NULL, '["Aplique silicone nos cantos críticos se o fabricante recomendar."]', '["Respeite o torque para não esmagar a junta."]', '2026-06-13T11:49:05.410+00:00', '2026-06-13T11:49:05.410+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-valve-cover-gasket-step-5', 'guide-valve-cover-gasket', 5, 'Remontagem e teste', 'Reconecte bobinas, cabos e mangueiras, ligue o motor e verifique se há vazamentos.', NULL, '["Confira novamente após o motor aquecer."]', '["Garanta que todas as conexões elétricas estejam firmes."]', '2026-06-13T11:49:05.435+00:00', '2026-06-13T11:49:05.435+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-coolant-step-1', 'guide-coolant', 1, 'Resfriamento do motor', 'Espere o motor esfriar completamente antes de iniciar o serviço.', NULL, '["Aproveite para revisar o estado de mangueiras."]', '["Risco sério de queimaduras."]', '2026-06-13T11:49:05.535+00:00', '2026-06-13T11:49:05.535+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-coolant-step-2', 'guide-coolant', 2, 'Drenagem do sistema', 'Com o motor frio, abra a tampa do radiador e a válvula de drenagem inferior.', NULL, '["Use recipiente grande para coletar todo o líquido."]', '[]', '2026-06-13T11:49:05.558+00:00', '2026-06-13T11:49:05.558+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-coolant-step-3', 'guide-coolant', 3, 'Lavagem (opcional)', 'Se necessário, adicione água destilada e ligue o motor brevemente para circular. Drene novamente.', NULL, '[]', '["Atenção ao calor residual."]', '2026-06-13T11:49:05.580+00:00', '2026-06-13T11:49:05.580+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-coolant-step-4', 'guide-coolant', 4, 'Reabastecimento', 'Coloque o novo líquido de arrefecimento até o nível máximo indicado no reservatório.', NULL, '["Misture de acordo com a concentração recomendada."]', '[]', '2026-06-13T11:49:05.622+00:00', '2026-06-13T11:49:05.622+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-coolant-step-5', 'guide-coolant', 5, 'Sangria do sistema', 'Ligue o motor e deixe funcionar até o eletroventilador acionar. Complete se necessário.', NULL, '["Verifique o nível após alguns quilômetros."]', '[]', '2026-06-13T11:49:05.648+00:00', '2026-06-13T11:49:05.648+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-1', 'guide-radiator', 1, 'Drenagem do sistema', 'Com o motor frio, drene todo o líquido de arrefecimento abrindo a válvula na base do radiador.', NULL, '["Coloque recipiente grande para recolher os 4,5L de líquido."]', '[]', '2026-06-13T11:49:05.769+00:00', '2026-06-13T11:49:05.769+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-2', 'guide-radiator', 2, 'Remoção de componentes frontais', 'Remova a grade dianteira, osfaróis e os defletores plásticos que bloqueiam o acesso ao radiador.', NULL, '["Organize parafusos e clipes para não perder nenhuma peça."]', '[]', '2026-06-13T11:49:05.808+00:00', '2026-06-13T11:49:05.808+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-3', 'guide-radiator', 3, 'Desconexão das mangueiras e conectores', 'Solte as abraçadeiras das mangueiras superior e inferior, e desconecte o conector do eletroventilador.', NULL, '["Marque as mangueiras para não inverter na montagem."]', '["Evite forçar as mangueiras velhas que podem estar endurecidas."]', '2026-06-13T11:49:05.839+00:00', '2026-06-13T11:49:05.839+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-4', 'guide-radiator', 4, 'Retirada do radiador', 'Remova os parafusos de fixação e levante o radiador com cuidado para não danificar as aletas.', NULL, '["Verifique o estado daspresilhas de borracha antivibrração."]', '[]', '2026-06-13T11:49:05.859+00:00', '2026-06-13T11:49:05.859+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-5', 'guide-radiator', 5, 'Instalação do radiador novo', 'Posicione o radiador novo com as presilhas, reconecte mangueiras, ventilador e instale os componentes frontais.', NULL, '["Não aperte demais as abraçadeiras das mangueiras."]', '[]', '2026-06-13T11:49:05.882+00:00', '2026-06-13T11:49:05.882+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-step-6', 'guide-radiator', 6, 'Reabastecimento e sangria', 'Coloque o líquido de arrefecimento, ligue o motor e deixe o sistema circular até o eletroventilador acionar.', NULL, '["Complete o nível após o primeiro aquecimento e verifique vazamentos."]', '["Nunca dirija com o nível de líquido baixo ou com superaquecimento."]', '2026-06-13T11:49:05.901+00:00', '2026-06-13T11:49:05.901+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-thermostat-step-1', 'guide-thermostat', 1, 'Resfriamento do sistema', 'Aguarde o motor esfriar completamente antes de iniciar o serviço.', NULL, '["Não trabalhe com o motor quente para evitar queimaduras."]', '["O líquido de arrefecimento pode estar quente e sob pressão."]', '2026-06-13T11:49:05.964+00:00', '2026-06-13T11:49:05.964+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-thermostat-step-2', 'guide-thermostat', 2, 'Drenagem parcial', 'Abra a tampa do vaso expansor e drene quantidade suficiente para acessar o termostato.', NULL, '["Coloque recipiente sob o motor para coletar o líquido."]', '[]', '2026-06-13T11:49:06.021+00:00', '2026-06-13T11:49:06.021+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-thermostat-step-3', 'guide-thermostat', 3, 'Acesso e remoção do termostato', 'Localize a carcaça do termostato na saída do motor, solte as abraçadeiras e retire o componente antigo.', NULL, '["Observe a posição da marca de fluxo antes de remover."]', '["Não force mangueiras para não quebrar os encaixes."]', '2026-06-13T11:49:06.042+00:00', '2026-06-13T11:49:06.042+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-thermostat-step-4', 'guide-thermostat', 4, 'Instalação do termostato novo', 'Coloque o novo termostato na posição correta com a mola voltada para baixo, recoloque a junta e as mangueiras.', NULL, '["Confirme que o sentido de fluxo está correto (indicado por seta ou marca)."]', '["Uma instalação invertida causa superaquecimento."]', '2026-06-13T11:49:06.091+00:00', '2026-06-13T11:49:06.091+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-thermostat-step-5', 'guide-thermostat', 5, 'Reabastecimento e teste', 'Complete o nível do líquido de arrefecimento, ligue o motor e observe a temperatura até o termostato abrir.', NULL, '["O motor deve atingir a temperatura de trabalho em alguns minutos."]', '["Observe se há vazamentos nas conexões após o aquecimento."]', '2026-06-13T11:49:06.119+00:00', '2026-06-13T11:49:06.119+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cooling-fan-step-1', 'guide-cooling-fan', 1, 'Desconexão da bateria', 'Para evitar curtos, desconecte o cabo negativo da bateria.', NULL, '[]', '[]', '2026-06-13T11:49:06.177+00:00', '2026-06-13T11:49:06.177+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cooling-fan-step-2', 'guide-cooling-fan', 2, 'Remoção da proteção', 'Remova protetores/defletores plásticos que atrapalham acesso ao ventilador.', NULL, '["Armazene os parafusos separados."]', '[]', '2026-06-13T11:49:06.213+00:00', '2026-06-13T11:49:06.213+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cooling-fan-step-3', 'guide-cooling-fan', 3, 'Desmontagem do conjunto', 'Afrouxe os parafusos do ventilador, solte o conector elétrico e retire o conjunto.', NULL, '[]', '["Evite forçar fios e conectores."]', '2026-06-13T11:49:06.266+00:00', '2026-06-13T11:49:06.266+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cooling-fan-step-4', 'guide-cooling-fan', 4, 'Instalação do novo ventilador', 'Instale o novo eletroventilador, prenda os parafusos e religue o conector.', NULL, '[]', '[]', '2026-06-13T11:49:06.302+00:00', '2026-06-13T11:49:06.302+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cooling-fan-step-5', 'guide-cooling-fan', 5, 'Recomposição e teste', 'Reinstale os protetores, conecte a bateria e ligue o carro até acionar o ventilador.', NULL, '["Observe o funcionamento pelo painel."]', '[]', '2026-06-13T11:49:06.339+00:00', '2026-06-13T11:49:06.339+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-water-pump-step-1', 'guide-water-pump', 1, 'Drenagem e preparação', 'Drene o líquido de arrefecimento pelo radiador e remova as proteções e correias de acesso ao motor.', NULL, '["Aproveite para trocar o líquido de arrefecimento."]', '["Faça o serviço com o motor totalmente frio para evitar queimaduras."]', '2026-06-13T11:49:06.408+00:00', '2026-06-13T11:49:06.408+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-water-pump-step-2', 'guide-water-pump', 2, 'Acesso à correia dentada', 'Remova a tampa da correia dentada e posicione o motor no ponto, travando comando e virabrequim.', NULL, '["Marque a posição do ponto antes de soltar a correia."]', '["Erro no ponto pode causar choque entre válvulas e pistões."]', '2026-06-13T11:49:06.426+00:00', '2026-06-13T11:49:06.426+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-water-pump-step-3', 'guide-water-pump', 3, 'Remoção da bomba antiga', 'Afrouxe o tensor, retire a correia dentada e solte os parafusos da bomba d''água, removendo-a.', NULL, '["Limpe a superfície de assentamento da bomba no bloco."]', '["Não gire o comando ou virabrequim com a correia removida."]', '2026-06-13T11:49:06.449+00:00', '2026-06-13T11:49:06.449+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-water-pump-step-4', 'guide-water-pump', 4, 'Instalação da bomba nova', 'Posicione a bomba nova com a junta, aperte no torque correto e reinstale a correia dentada no ponto.', NULL, '["Confira o alinhamento das marcas de ponto antes de tensionar a correia."]', '["Tensione a correia conforme especificação do fabricante."]', '2026-06-13T11:49:06.472+00:00', '2026-06-13T11:49:06.472+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-water-pump-step-5', 'guide-water-pump', 5, 'Abastecimento e teste', 'Reabasteça com líquido de arrefecimento, faça a sangria do ar, ligue o motor e verifique vazamentos e temperatura.', NULL, '["Acompanhe o ventilador ligar para confirmar a circulação."]', '["Elimine o ar do sistema para evitar superaquecimento."]', '2026-06-13T11:49:06.493+00:00', '2026-06-13T11:49:06.493+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-hoses-step-1', 'guide-radiator-hoses', 1, 'Drenagem do líquido', 'Com o motor frio, drene o líquido de arrefecimento para um recipiente abrindo o dreno do radiador.', NULL, '["Guarde o líquido limpo se for reutilizar."]', '["Nunca abra o sistema com o motor quente."]', '2026-06-13T11:49:06.596+00:00', '2026-06-13T11:49:06.596+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-hoses-step-2', 'guide-radiator-hoses', 2, 'Remoção das mangueiras antigas', 'Solte as abraçadeiras e retire as mangueiras superior e inferior do radiador e do motor.', NULL, '["Gire levemente a mangueira para soltar do bocal."]', '["Mangueiras ressecadas podem quebrar; tenha cuidado com o bocal."]', '2026-06-13T11:49:06.616+00:00', '2026-06-13T11:49:06.616+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-hoses-step-3', 'guide-radiator-hoses', 3, 'Instalação das mangueiras novas', 'Encaixe as mangueiras novas nos bocais e fixe com abraçadeiras novas firmemente.', NULL, '["Posicione as abraçadeiras após o ressalto do bocal."]', '["Não aperte demais a ponto de cortar a mangueira."]', '2026-06-13T11:49:06.637+00:00', '2026-06-13T11:49:06.637+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-radiator-hoses-step-4', 'guide-radiator-hoses', 4, 'Abastecimento e teste', 'Reabasteça o sistema, faça a sangria do ar, ligue o motor e verifique vazamentos.', NULL, '["Acompanhe a temperatura no painel."]', '["Elimine o ar do sistema para evitar superaquecimento."]', '2026-06-13T11:49:06.655+00:00', '2026-06-13T11:49:06.655+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-filter-step-1', 'guide-fuel-filter', 1, 'Alívio da pressão do sistema', 'Com o motor desligado, alivie a pressão da linha de combustível conforme o procedimento seguro do veículo.', NULL, '["Trabalhe em local ventilado e longe de fontes de ignição."]', '["Combustível é inflamável e exige cuidado extremo."]', '2026-06-13T11:49:06.736+00:00', '2026-06-13T11:49:06.736+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-filter-step-2', 'guide-fuel-filter', 2, 'Acesso ao filtro antigo', 'Localize o filtro próximo ao tanque, solte as abraçadeiras e posicione pano para conter respingos.', NULL, '["Observe o sentido do fluxo marcado no corpo do filtro."]', '[]', '2026-06-13T11:49:06.758+00:00', '2026-06-13T11:49:06.758+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-filter-step-3', 'guide-fuel-filter', 3, 'Instalação do filtro novo', 'Remova o filtro usado, instale o novo no mesmo sentido e reaplique as travas ou abraçadeiras.', NULL, '["Confirme se as mangueiras assentaram completamente nos encaixes."]', '["Não reutilize conexões danificadas."]', '2026-06-13T11:49:06.780+00:00', '2026-06-13T11:49:06.780+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-filter-step-4', 'guide-fuel-filter', 4, 'Teste de estanqueidade', 'Ligue a ignição para pressurizar o sistema e verifique se não há vazamentos antes de dar partida.', NULL, '["Repita a verificação com o motor em funcionamento por alguns minutos."]', '[]', '2026-06-13T11:49:06.805+00:00', '2026-06-13T11:49:06.805+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-pump-step-1', 'guide-fuel-pump', 1, 'Despressurização e segurança', 'Desligue o motor, retire o fusível da bomba e dê partida para aliviar a pressão. Desconecte a bateria.', NULL, '["Trabalhe com o tanque com pouco combustível."]', '["Não fume nem use chamas próximas; combustível é inflamável.","Despressurize o sistema antes de abrir as conexões."]', '2026-06-13T11:49:06.872+00:00', '2026-06-13T11:49:06.872+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-pump-step-2', 'guide-fuel-pump', 2, 'Acesso ao tanque', 'Remova o banco traseiro ou a tampa de acesso sob o assoalho para chegar ao flange da bomba.', NULL, '["Limpe a região ao redor do flange antes de abrir."]', '["Evite a entrada de sujeira no tanque."]', '2026-06-13T11:49:06.892+00:00', '2026-06-13T11:49:06.892+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-pump-step-3', 'guide-fuel-pump', 3, 'Remoção da bomba antiga', 'Desconecte o chicote e as mangueiras, solte o anel de fixação e retire o conjunto da bomba com cuidado.', NULL, '["Observe a posição da boia e do filtro de sucção."]', '["Cuidado com o vazamento de combustível ao retirar o conjunto."]', '2026-06-13T11:49:06.924+00:00', '2026-06-13T11:49:06.924+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-pump-step-4', 'guide-fuel-pump', 4, 'Instalação da bomba nova', 'Instale a bomba nova com o anel de vedação novo, reconecte mangueiras e chicote, e fixe o anel de retenção.', NULL, '["Alinhe a marca de posição do flange com o tanque."]', '["Garanta a vedação correta para evitar vazamento de vapores."]', '2026-06-13T11:49:06.945+00:00', '2026-06-13T11:49:06.945+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-pump-step-5', 'guide-fuel-pump', 5, 'Teste do sistema', 'Reconecte a bateria e o fusível, ligue a ignição algumas vezes para pressurizar e verifique vazamentos e partida.', NULL, '["A bomba deve fazer um zumbido ao ligar a ignição."]', '["Verifique a ausência de vazamentos antes de dar partida."]', '2026-06-13T11:49:06.980+00:00', '2026-06-13T11:49:06.980+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-injectors-step-1', 'guide-fuel-injectors', 1, 'Despressurização do sistema', 'Retire o fusível da bomba e dê partida para aliviar a pressão, depois desconecte a bateria.', NULL, '["Trabalhe em local ventilado."]', '["Despressurize o sistema antes de abrir as conexões de combustível."]', '2026-06-13T11:49:07.056+00:00', '2026-06-13T11:49:07.056+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-injectors-step-2', 'guide-fuel-injectors', 2, 'Remoção da flauta e injetores', 'Desconecte os chicotes, solte a flauta de combustível e retire os bicos injetores com cuidado.', NULL, '["Identifique cada injetor pela ordem dos cilindros."]', '["Evite a entrada de sujeira no coletor de admissão."]', '2026-06-13T11:49:07.075+00:00', '2026-06-13T11:49:07.075+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-injectors-step-3', 'guide-fuel-injectors', 3, 'Limpeza dos injetores', 'Faça a limpeza dos bicos com o kit apropriado, removendo resíduos e testando a pulverização.', NULL, '["Substitua os anéis de vedação dos bicos por novos."]', '["Não use objetos metálicos para desobstruir os orifícios."]', '2026-06-13T11:49:07.096+00:00', '2026-06-13T11:49:07.096+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuel-injectors-step-4', 'guide-fuel-injectors', 4, 'Remontagem e teste', 'Reinstale os injetores e a flauta, reconecte os chicotes e a bateria, e verifique a marcha lenta e vazamentos.', NULL, '["A marcha lenta deve estabilizar após a limpeza."]', '["Confira a ausência de vazamentos de combustível antes de rodar."]', '2026-06-13T11:49:07.118+00:00', '2026-06-13T11:49:07.118+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-lambda-sensor-step-1', 'guide-lambda-sensor', 1, 'Localização do sensor', 'Localize o sensor lambda no tubo de escape, próximo ao coletor, e desconecte seu chicote elétrico.', NULL, '["Trabalhe com o escapamento frio para evitar queimaduras."]', '["Aguarde o sistema de escape esfriar completamente."]', '2026-06-13T11:49:07.186+00:00', '2026-06-13T11:49:07.186+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-lambda-sensor-step-2', 'guide-lambda-sensor', 2, 'Remoção do sensor antigo', 'Com a chave apropriada, solte e remova o sensor lambda do tubo de escape.', NULL, '["Se estiver muito preso, aplique óleo desengripante e aguarde."]', '["Não force a rosca do escapamento para não danificá-la."]', '2026-06-13T11:49:07.211+00:00', '2026-06-13T11:49:07.211+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-lambda-sensor-step-3', 'guide-lambda-sensor', 3, 'Instalação do sensor novo', 'Aplique graxa anti-engripante na rosca e instale o sensor novo, apertando no torque correto.', NULL, '["Não deixe a graxa atingir a ponta sensora do sensor."]', '["Aperto excessivo pode danificar o sensor ou a rosca."]', '2026-06-13T11:49:07.233+00:00', '2026-06-13T11:49:07.233+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-lambda-sensor-step-4', 'guide-lambda-sensor', 4, 'Reconexão e teste', 'Reconecte o chicote, apague o código de falha com o scanner e teste a marcha lenta.', NULL, '["A luz de injeção deve apagar após o reset."]', '["Verifique se o conector está bem encaixado."]', '2026-06-13T11:49:07.256+00:00', '2026-06-13T11:49:07.256+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-blades-step-1', 'guide-wiper-blades', 1, 'Posicionamento dos braços', 'Levante os braços do limpador do para-brisa até travarem na posição de serviço.', NULL, '[]', '[]', '2026-06-13T11:49:07.339+00:00', '2026-06-13T11:49:07.339+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-blades-step-2', 'guide-wiper-blades', 2, 'Remoção das palhetas antigas', 'Pressione a trava e deslize a palheta antiga para retirá-la do braço.', NULL, '["Cuidado com retorno do braço sem palheta para não quebrar vidro."]', '[]', '2026-06-13T11:49:07.360+00:00', '2026-06-13T11:49:07.360+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-blades-step-3', 'guide-wiper-blades', 3, 'Instalação das novas palhetas', 'Encaixe a nova palheta até ouvir o clique de travamento.', NULL, '["Compare o tamanho das palhetas com as antigas antes de instalar."]', '[]', '2026-06-13T11:49:07.379+00:00', '2026-06-13T11:49:07.379+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-blades-step-4', 'guide-wiper-blades', 4, 'Teste', 'Abaixe os braços e teste o limpador para garantir funcionamento correto.', NULL, '[]', '[]', '2026-06-13T11:49:07.402+00:00', '2026-06-13T11:49:07.402+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-arms-step-1', 'guide-wiper-arms', 1, 'Posicionamento para serviço', 'Levante os braços do limpador e posicione as palhetas na posição de teste ou remoção (conforme o veículo).', NULL, '["Coloque um pano sobre o para-brisa para proteger em caso de queda do braço."]', '["Cuidado para não deixar o braço voltar rápido e quebrar o vidro."]', '2026-06-13T11:49:07.472+00:00', '2026-06-13T11:49:07.472+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-arms-step-2', 'guide-wiper-arms', 2, 'Remoção do braço antigo', 'Remova a tampa decorativa do eixo, solte a porca de fixação com chave 13mm e puxe o braço para fora.', NULL, '["Se o braço estiver preso, gire levemente para soltar."]', '[]', '2026-06-13T11:49:07.494+00:00', '2026-06-13T11:49:07.494+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-arms-step-3', 'guide-wiper-arms', 3, 'Instalação do braço novo', 'Limpe o eixo, posicione o braço novo na mesma angulação aproximada e aperte a porca sem totalmente fixer.', NULL, '["Ative o limpador para verificar a posição antes do aperto final."]', '[]', '2026-06-13T11:49:07.518+00:00', '2026-06-13T11:49:07.518+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wiper-arms-step-4', 'guide-wiper-arms', 4, 'Ajuste e fixação final', 'Ligue a ignição (sem motor) para ativar o limpador e ajuste a posição do braço para varrer corretamente o para-brisa.', NULL, '["O braço deve varrer cerca de 2-3cm da borda do para-brisa e deixar uma faixa limpa."]', '["Desligue o limpador antes de soltá-lo para não danificar o vidro."]', '2026-06-13T11:49:07.539+00:00', '2026-06-13T11:49:07.539+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-washer-fluid-step-1', 'guide-washer-fluid', 1, 'Localização do reservatório', 'Abra o capô e localize o reservatório do esguicho, identificado pelo símbolo de para-brisa na tampa.', NULL, '["Não confunda com o vaso de expansão do líquido de arrefecimento."]', '["Nunca abasteça o reservatório do limpador com líquido de arrefecimento."]', '2026-06-13T11:49:07.610+00:00', '2026-06-13T11:49:07.610+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-washer-fluid-step-2', 'guide-washer-fluid', 2, 'Abastecimento e teste', 'Abasteça com o fluido apropriado até o nível indicado, feche a tampa e teste os esguichos.', NULL, '["Dilua o concentrado conforme as instruções do fabricante."]', '["Não use água com sabão comum, pois pode entupir os esguichos."]', '2026-06-13T11:49:07.637+00:00', '2026-06-13T11:49:07.637+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-battery-step-1', 'guide-battery', 1, 'Segurança e acesso', 'Desligue o veículo, abra o capô e coloque luvas para evitar choque.', NULL, '["Tenha cuidado para não encostar metal nos terminais."]', '["Nunca mexa na bateria com o carro ligado."]', '2026-06-13T11:49:07.717+00:00', '2026-06-13T11:49:07.717+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-battery-step-2', 'guide-battery', 2, 'Desconexão dos terminais', 'Retire primeiro o cabo negativo (preto), depois o positivo (vermelho), afrouxando com chave 10mm.', NULL, '["Marque os terminais para não inverter na montagem."]', '[]', '2026-06-13T11:49:07.740+00:00', '2026-06-13T11:49:07.740+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-battery-step-3', 'guide-battery', 3, 'Remoção da bateria antiga', 'Remova o suporte da bateria com chave 13mm e retire a bateria com cuidado.', NULL, '["Evite inclinar a bateria."]', '[]', '2026-06-13T11:49:07.767+00:00', '2026-06-13T11:49:07.767+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-battery-step-4', 'guide-battery', 4, 'Instalação da nova bateria', 'Coloque a nova bateria, fixe o suporte e conecte primeiro o cabo positivo e depois o negativo.', NULL, '["Aperte os terminais, mas sem excesso."]', '[]', '2026-06-13T11:49:07.790+00:00', '2026-06-13T11:49:07.790+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-battery-step-5', 'guide-battery', 5, 'Teste e verificação', 'Ligue o carro e verifique funcionamento dos sistemas elétricos.', NULL, '["Verifique se luzes do painel acendem normalmente."]', '[]', '2026-06-13T11:49:07.809+00:00', '2026-06-13T11:49:07.809+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuse-box-step-1', 'guide-fuse-box', 1, 'Identificação do problema', 'Verifique se múltiplos circuitos estão falhando simultaneamente e localize a caixa de fusíveis.', NULL, '["Inspecione visualmente a caixa em busca de marcas de queimado ou derretido."]', '["Antes de trocar, verifique se não há curto-circuito na origem do problema."]', '2026-06-13T11:49:07.874+00:00', '2026-06-13T11:49:07.874+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuse-box-step-2', 'guide-fuse-box', 2, 'Desconexão da bateria', 'Desligue o cabo negativo da bateria antes de mexer na caixa de fusíveis.', NULL, '[]', '["Nunca trabalhe no sistema elétrico com a bateria conectada."]', '2026-06-13T11:49:07.896+00:00', '2026-06-13T11:49:07.896+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuse-box-step-3', 'guide-fuse-box', 3, 'Remoção da caixa antiga', 'Tire a tampa da caixa, fotografe a disposição dos fusíveis, desconecte todos os chicotes e remova a caixa.', NULL, '["Etiquetar cada chicote facilita a remontagem."]', '["Nãoforce os conectores para não danificar os terminais."]', '2026-06-13T11:49:07.916+00:00', '2026-06-13T11:49:07.916+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuse-box-step-4', 'guide-fuse-box', 4, 'Instalação da caixa nova', 'Posicione a caixa nova, reconecte todos os chicotes na ordem correta e recoloque os fusíveis conforme foto.', NULL, '["Confirme que cada fusível está na amperagem correta."]', '["Fusíveis de amperagem errada podem causar falhas ou danos."]', '2026-06-13T11:49:07.936+00:00', '2026-06-13T11:49:07.936+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuse-box-step-5', 'guide-fuse-box', 5, 'Teste dos circuitos', 'Conecte a bateria, ligue sistemas um a um e verifique se todos os circuitos funcionam corretamente.', NULL, '["Se algum circuito não funcionar, verifique o fusível e as conexões."]', '[]', '2026-06-13T11:49:07.954+00:00', '2026-06-13T11:49:07.954+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuses-step-1', 'guide-fuses', 1, 'Localização da caixa de fusíveis', 'Abra a tampa da caixa de fusíveis no painel ou compartimento do motor.', NULL, '[]', '[]', '2026-06-13T11:49:08.022+00:00', '2026-06-13T11:49:08.022+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuses-step-2', 'guide-fuses', 2, 'Identificação do fusível queimado', 'Verifique o diagrama e observe quais fusíveis estão queimados (fio partido dentro do fusível).', NULL, '["Use a lanterna para melhor visualização."]', '[]', '2026-06-13T11:49:08.046+00:00', '2026-06-13T11:49:08.046+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuses-step-3', 'guide-fuses', 3, 'Remoção e colocação do novo fusível', 'Utilize a pinça plástica para retirar o fusível queimado e substituir por um novo, de mesma amperagem.', NULL, '["Confirme a cor e amperagem do fusível."]', '["Nunca utilize alumínio ou outros objetos como substituto."]', '2026-06-13T11:49:08.066+00:00', '2026-06-13T11:49:08.066+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-fuses-step-4', 'guide-fuses', 4, 'Fechamento e teste', 'Recoloque a tampa da caixa de fusíveis e teste o funcionamento do sistema afetado.', NULL, '[]', '[]', '2026-06-13T11:49:08.085+00:00', '2026-06-13T11:49:08.085+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-alternator-step-1', 'guide-alternator', 1, 'Desconexão da bateria', 'Desconecte o terminal negativo da bateria para trabalhar com segurança no sistema elétrico.', NULL, '["Anote o código do rádio se houver."]', '["Sempre desconecte a bateria antes de mexer no alternador."]', '2026-06-13T11:49:08.155+00:00', '2026-06-13T11:49:08.155+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-alternator-step-2', 'guide-alternator', 2, 'Remoção da correia auxiliar', 'Alivie o tensor da correia auxiliar (poly-V) e remova a correia da polia do alternador.', NULL, '["Fotografe o trajeto da correia para a remontagem."]', '["Cuidado com o retorno do tensor sob tensão."]', '2026-06-13T11:49:08.174+00:00', '2026-06-13T11:49:08.174+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-alternator-step-3', 'guide-alternator', 3, 'Desconexão e remoção do alternador', 'Desconecte os cabos elétricos do alternador, solte os parafusos de fixação e retire a peça.', NULL, '["Identifique cada cabo para reconectar corretamente."]', '["O alternador é pesado; segure-o ao soltar o último parafuso."]', '2026-06-13T11:49:08.197+00:00', '2026-06-13T11:49:08.197+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-alternator-step-4', 'guide-alternator', 4, 'Instalação do alternador novo', 'Posicione o alternador novo, aperte os parafusos no torque correto e reconecte os cabos elétricos.', NULL, '["Aproveite para trocar a correia auxiliar se estiver desgastada."]', '["Garanta que os cabos estejam firmes para evitar mau contato."]', '2026-06-13T11:49:08.223+00:00', '2026-06-13T11:49:08.223+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-alternator-step-5', 'guide-alternator', 5, 'Remontagem e teste de carga', 'Reinstale a correia, reconecte a bateria, ligue o motor e meça a tensão de carga com o multímetro.', NULL, '["A tensão de carga deve ficar em torno de 13,8V a 14,4V."]', '["A luz da bateria deve apagar após a partida."]', '2026-06-13T11:49:08.243+00:00', '2026-06-13T11:49:08.243+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-starter-motor-step-1', 'guide-starter-motor', 1, 'Desconexão da bateria', 'Desconecte o terminal negativo da bateria para evitar curto-circuito durante o serviço.', NULL, '["Anote o código do rádio se houver."]', '["Nunca mexa no motor de partida com a bateria conectada."]', '2026-06-13T11:49:08.313+00:00', '2026-06-13T11:49:08.313+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-starter-motor-step-2', 'guide-starter-motor', 2, 'Acesso ao motor de partida', 'Eleve o veículo com segurança e localize o motor de partida na junção do motor com o câmbio.', NULL, '["Pode ser necessário remover componentes que bloqueiam o acesso."]', '["Apoie o veículo em cavaletes."]', '2026-06-13T11:49:08.338+00:00', '2026-06-13T11:49:08.338+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-starter-motor-step-3', 'guide-starter-motor', 3, 'Desconexão e remoção', 'Desconecte os cabos do solenoide, solte os parafusos de fixação e retire o motor de partida.', NULL, '["Identifique o cabo grosso (positivo) e o fino (solenoide)."]', '["O motor de partida é pesado; segure ao soltar o último parafuso."]', '2026-06-13T11:49:08.361+00:00', '2026-06-13T11:49:08.361+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-starter-motor-step-4', 'guide-starter-motor', 4, 'Instalação do motor novo', 'Posicione o motor de partida novo, aperte os parafusos no torque correto e reconecte os cabos.', NULL, '["Confira o engrenamento com o volante do motor."]', '["Aperte bem o cabo positivo para evitar aquecimento e mau contato."]', '2026-06-13T11:49:08.386+00:00', '2026-06-13T11:49:08.386+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-starter-motor-step-5', 'guide-starter-motor', 5, 'Reconexão e teste', 'Reconecte a bateria, dê a partida e verifique se o motor aciona normalmente e sem ruídos.', NULL, '["A partida deve ser firme e sem cliques."]', '["Verifique se não há ruído metálico de engrenagem ao acionar."]', '2026-06-13T11:49:08.406+00:00', '2026-06-13T11:49:08.406+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-headlight-bulb-step-1', 'guide-headlight-bulb', 1, 'Acesso à lanterna', 'Abra o capô, localize a traseira do farol e remova a tampa de proteção.', NULL, '[]', '[]', '2026-06-13T11:49:08.496+00:00', '2026-06-13T11:49:08.496+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-headlight-bulb-step-2', 'guide-headlight-bulb', 2, 'Desconexão e retirada', 'Desconecte o conector elétrico e remova a lâmpada girando levemente.', NULL, '["Use luva de algodão para não tocar o bulbo."]', '[]', '2026-06-13T11:49:08.517+00:00', '2026-06-13T11:49:08.517+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-headlight-bulb-step-3', 'guide-headlight-bulb', 3, 'Instalação da nova lâmpada', 'Coloque a nova lâmpada, conecte o chicote e ajuste a tampa.', NULL, '[]', '["Não toque diretamente no vidro da lâmpada."]', '2026-06-13T11:49:08.538+00:00', '2026-06-13T11:49:08.538+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-headlight-bulb-step-4', 'guide-headlight-bulb', 4, 'Teste e conferência', 'Ligue o farol e verifique o funcionamento e o alinhamento.', NULL, '["Faça o teste em local seguro de frente para uma parede."]', '[]', '2026-06-13T11:49:08.569+00:00', '2026-06-13T11:49:08.569+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tail-light-bulb-step-1', 'guide-tail-light-bulb', 1, 'Acesso ao conjunto traseiro', 'Abra o porta-malas e remova o acabamento ou a tampa de acesso à lanterna.', NULL, '["Guarde os clipes e parafusos para a remontagem."]', '[]', '2026-06-13T11:49:08.649+00:00', '2026-06-13T11:49:08.649+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tail-light-bulb-step-2', 'guide-tail-light-bulb', 2, 'Retirada do soquete', 'Gire o soquete da lâmpada no sentido indicado e retire-o do conjunto da lanterna.', NULL, '["Identifique a posição correta da lâmpada antes de remover."]', '[]', '2026-06-13T11:49:08.671+00:00', '2026-06-13T11:49:08.671+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tail-light-bulb-step-3', 'guide-tail-light-bulb', 3, 'Troca da lâmpada', 'Remova a lâmpada queimada, instale a nova e encaixe novamente o soquete.', NULL, '["Teste luz de posição e freio antes de fechar o acabamento."]', '["Use o modelo correto para evitar superaquecimento."]', '2026-06-13T11:49:08.692+00:00', '2026-06-13T11:49:08.692+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tail-light-bulb-step-4', 'guide-tail-light-bulb', 4, 'Fechamento e teste', 'Reinstale o acabamento e confira o funcionamento com o pedal de freio acionado.', NULL, '["Peça ajuda de outra pessoa para validar as luzes traseiras."]', '[]', '2026-06-13T11:49:08.714+00:00', '2026-06-13T11:49:08.714+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-turn-signal-bulb-step-1', 'guide-turn-signal-bulb', 1, 'Localização do conjunto', 'Acesse o conjunto óptico correspondente e localize o soquete da lâmpada da seta.', NULL, '["Identifique previamente qual lado está com defeito."]', '[]', '2026-06-13T11:49:08.778+00:00', '2026-06-13T11:49:08.778+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-turn-signal-bulb-step-2', 'guide-turn-signal-bulb', 2, 'Remoção do soquete', 'Gire o soquete e retire-o do conjunto com cuidado para não forçar o chicote.', NULL, '["Observe a posição do encaixe para facilitar a remontagem."]', '[]', '2026-06-13T11:49:08.798+00:00', '2026-06-13T11:49:08.798+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-turn-signal-bulb-step-3', 'guide-turn-signal-bulb', 3, 'Substituição da lâmpada', 'Retire a lâmpada queimada e instale a nova com o encaixe correto.', NULL, '["Teste a seta antes de remontar todo o conjunto."]', '["Não misture lâmpadas de potência diferente."]', '2026-06-13T11:49:08.819+00:00', '2026-06-13T11:49:08.819+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-turn-signal-bulb-step-4', 'guide-turn-signal-bulb', 4, 'Teste do pisca', 'Acione a seta e o alerta para confirmar a frequência correta de piscada.', NULL, '["Pisca muito rápido costuma indicar lâmpada incorreta ou defeito no circuito."]', '[]', '2026-06-13T11:49:08.840+00:00', '2026-06-13T11:49:08.840+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-reverse-light-bulb-step-1', 'guide-reverse-light-bulb', 1, 'Acesso à lanterna traseira', 'Abra o porta-malas e remova a tampa de acesso ou os parafusos da lanterna traseira.', NULL, '["Identifique o soquete da lâmpada de ré pela cor do fio."]', '[]', '2026-06-13T11:49:08.898+00:00', '2026-06-13T11:49:08.898+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-reverse-light-bulb-step-2', 'guide-reverse-light-bulb', 2, 'Substituição da lâmpada', 'Gire o soquete para soltá-lo, retire a lâmpada queimada pressionando e girando, e instale a nova.', NULL, '["Não toque o vidro da lâmpada com os dedos."]', '["Use a lâmpada correta de 21W para não danificar o soquete."]', '2026-06-13T11:49:08.918+00:00', '2026-06-13T11:49:08.918+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-reverse-light-bulb-step-3', 'guide-reverse-light-bulb', 3, 'Teste e fechamento', 'Reinstale o soquete e a lanterna, engate a ré com a ignição ligada e confirme o acendimento.', NULL, '["Peça ajuda para confirmar a luz por fora do veículo."]', '[]', '2026-06-13T11:49:08.940+00:00', '2026-06-13T11:49:08.940+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-license-plate-light-step-1', 'guide-license-plate-light', 1, 'Remoção da luminária', 'Solte os parafusos ou pressione as travas da luminária da placa para removê-la.', NULL, '["Use uma chave de fenda pequena para soltar as travas com cuidado."]', '["Não force o plástico para não quebrar a luminária."]', '2026-06-13T11:49:09.002+00:00', '2026-06-13T11:49:09.002+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-license-plate-light-step-2', 'guide-license-plate-light', 2, 'Substituição da lâmpada', 'Retire a lâmpada torpedo dos contatos pressionando levemente e instale a lâmpada nova.', NULL, '["Não toque o vidro da lâmpada com os dedos."]', '[]', '2026-06-13T11:49:09.024+00:00', '2026-06-13T11:49:09.024+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-license-plate-light-step-3', 'guide-license-plate-light', 3, 'Teste e recolocação', 'Recoloque a luminária, ligue os faróis e confirme o acendimento da iluminação da placa.', NULL, '["Verifique se a luz ilumina bem toda a placa."]', '[]', '2026-06-13T11:49:09.046+00:00', '2026-06-13T11:49:09.046+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-pads-step-1', 'guide-front-brake-pads', 1, 'Elevação do veículo', 'Com o carro estacionado e travado, solte os parafusos da roda e eleve usando o macaco.', NULL, '["Utilize cavaletes para segurança extra."]', '["Nunca deixe o veículo apoiado só no macaco."]', '2026-06-13T11:49:09.129+00:00', '2026-06-13T11:49:09.129+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-pads-step-2', 'guide-front-brake-pads', 2, 'Remoção da roda e pinça', 'Tire a roda, solte parafusos da pinça de freio e afaste a pinça.', NULL, '[]', '[]', '2026-06-13T11:49:09.153+00:00', '2026-06-13T11:49:09.153+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-pads-step-3', 'guide-front-brake-pads', 3, 'Remoção das pastilhas gastas', 'Retire as pastilhas velhas e limpe a área com pano. Verifique desgaste irregular.', NULL, '["Aplique desengripante nos parafusos se necessário."]', '["Não respire pó do freio."]', '2026-06-13T11:49:09.176+00:00', '2026-06-13T11:49:09.176+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-pads-step-4', 'guide-front-brake-pads', 4, 'Instalação das pastilhas novas', 'Coloque as pastilhas novas, aplique graxa cobreada onde recomendado, recoloque a pinça.', NULL, '[]', '[]', '2026-06-13T11:49:09.213+00:00', '2026-06-13T11:49:09.213+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-pads-step-5', 'guide-front-brake-pads', 5, 'Montagem da roda e teste', 'Recoloque a roda, aperte os parafusos e baixe o carro. Antes de rodar, pressione o pedal.', NULL, '["Faça um teste leve de frenagem antes de pegar velocidade."]', '["Pedal pode ficar baixo até o assentamento das pastilhas."]', '2026-06-13T11:49:09.249+00:00', '2026-06-13T11:49:09.249+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-pads-step-1', 'guide-rear-brake-pads', 1, 'Elevação e segurança', 'Solte os parafusos da roda, eleve o veículo e apoie com segurança em cavaletes.', NULL, '["Acione o freio de estacionamento antes de iniciar."]', '["Nunca permaneça sob o carro sem apoio adequado."]', '2026-06-13T11:49:09.318+00:00', '2026-06-13T11:49:09.318+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-pads-step-2', 'guide-rear-brake-pads', 2, 'Acesso à pinça traseira', 'Remova a roda e solte a pinça para ter acesso às pastilhas antigas.', NULL, '["Inspecione o estado dos pinos-guia."]', '[]', '2026-06-13T11:49:09.339+00:00', '2026-06-13T11:49:09.339+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-pads-step-3', 'guide-rear-brake-pads', 3, 'Substituição das pastilhas', 'Retire as pastilhas gastas, recue o pistão e instale o novo conjunto.', NULL, '["Aplique lubrificação apenas nos pontos recomendados."]', '["Não contamine o material de atrito das pastilhas."]', '2026-06-13T11:49:09.361+00:00', '2026-06-13T11:49:09.361+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-pads-step-4', 'guide-rear-brake-pads', 4, 'Montagem e teste', 'Reinstale a pinça e a roda, baixe o veículo e bombeie o pedal antes de sair.', NULL, '["Faça um teste de baixa velocidade para assentar as pastilhas."]', '[]', '2026-06-13T11:49:09.382+00:00', '2026-06-13T11:49:09.382+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-brake-fluid-step-1', 'guide-brake-fluid', 1, 'Preparação do reservatório', 'Abra o capô, limpe a tampa do reservatório e retire o fluido antigo com seringa.', NULL, '["Proteja a pintura, pois o fluido agride superfícies pintadas."]', '["Use luvas e óculos de proteção."]', '2026-06-13T11:49:09.460+00:00', '2026-06-13T11:49:09.460+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-brake-fluid-step-2', 'guide-brake-fluid', 2, 'Abastecimento inicial', 'Preencha o reservatório com fluido novo até o nível máximo.', NULL, '["Mantenha sempre o nível acima do mínimo durante toda a sangria."]', '[]', '2026-06-13T11:49:09.486+00:00', '2026-06-13T11:49:09.486+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-brake-fluid-step-3', 'guide-brake-fluid', 3, 'Sangria das rodas', 'Sangre o sistema na ordem recomendada, recolhendo o fluido antigo até a saída ficar limpa.', NULL, '["Peça ajuda para acionar o pedal durante a sangria."]', '["Não deixe o reservatório secar."]', '2026-06-13T11:49:09.512+00:00', '2026-06-13T11:49:09.512+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-brake-fluid-step-4', 'guide-brake-fluid', 4, 'Conferência do pedal', 'Feche os sangradores, ajuste o nível final e teste a firmeza do pedal com o carro parado.', NULL, '["Verifique se não há vazamentos nas rodas e no cilindro mestre."]', '["Se o pedal continuar esponjoso, não rode com o veículo."]', '2026-06-13T11:49:09.539+00:00', '2026-06-13T11:49:09.539+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-disc-step-1', 'guide-front-brake-disc', 1, 'Remoção da roda', 'Afrouxe as porcas, eleve a dianteira com segurança, apoie em cavaletes e retire a roda.', NULL, '["Afrouxe as porcas antes de levantar o carro."]', '["Apoie o veículo em cavaletes, nunca apenas no macaco."]', '2026-06-13T11:49:09.618+00:00', '2026-06-13T11:49:09.618+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-disc-step-2', 'guide-front-brake-disc', 2, 'Remoção da pinça e pastilhas', 'Solte os parafusos da pinça de freio, retire-a e remova as pastilhas, apoiando a pinça sem esticar a mangueira.', NULL, '["Pendure a pinça com um arame para não forçar a mangueira."]', '["Não deixe a pinça pendurada pela mangueira de freio."]', '2026-06-13T11:49:09.642+00:00', '2026-06-13T11:49:09.642+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-disc-step-3', 'guide-front-brake-disc', 3, 'Remoção do disco antigo', 'Solte o suporte da pinça e os parafusos de fixação do disco, removendo o disco antigo do cubo.', NULL, '["Se o disco estiver preso, bata levemente com martelo de borracha."]', '["Limpe a face de contato do cubo antes de instalar o novo disco."]', '2026-06-13T11:49:09.668+00:00', '2026-06-13T11:49:09.668+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-disc-step-4', 'guide-front-brake-disc', 4, 'Instalação do disco novo', 'Limpe o disco novo com limpa-freios, instale-o no cubo e recoloque o suporte e as pastilhas novas.', NULL, '["Recolha o pistão da pinça com o grampo para encaixar as pastilhas novas."]', '["Remova a película protetora antiferrugem do disco novo."]', '2026-06-13T11:49:09.691+00:00', '2026-06-13T11:49:09.691+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-front-brake-disc-step-5', 'guide-front-brake-disc', 5, 'Montagem e teste', 'Recoloque a roda, aperte as porcas no torque correto, bombeie o pedal e teste o freio em baixa velocidade.', NULL, '["Bombeie o pedal até ele firmar antes de rodar."]', '["Faça a frenagem de assentamento com cuidado nos primeiros quilômetros."]', '2026-06-13T11:49:09.715+00:00', '2026-06-13T11:49:09.715+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-drum-step-1', 'guide-rear-brake-drum', 1, 'Remoção da roda', 'Solte as porcas, eleve a traseira com segurança, apoie em cavaletes e retire a roda.', NULL, '["Solte o freio de mão antes de retirar o tambor."]', '["Apoie o veículo em cavaletes, nunca apenas no macaco."]', '2026-06-13T11:49:09.799+00:00', '2026-06-13T11:49:09.799+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-drum-step-2', 'guide-rear-brake-drum', 2, 'Remoção do tambor antigo', 'Retire o tambor de freio; se estiver preso, afrouxe o regulador das lonas e bata levemente.', NULL, '["Bata com martelo de borracha ao redor do tambor para soltar."]', '["Não respire a poeira das lonas; pode conter material nocivo."]', '2026-06-13T11:49:09.827+00:00', '2026-06-13T11:49:09.827+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-drum-step-3', 'guide-rear-brake-drum', 3, 'Inspeção e limpeza', 'Inspecione as lonas, molas e o cilindro de roda, limpando o conjunto com limpa-freios.', NULL, '["Aproveite para trocar as lonas se estiverem desgastadas."]', '["Verifique se o cilindro de roda não está vazando fluido."]', '2026-06-13T11:49:09.873+00:00', '2026-06-13T11:49:09.873+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-drum-step-4', 'guide-rear-brake-drum', 4, 'Instalação do tambor novo', 'Limpe o tambor novo com limpa-freios e instale-o no eixo, ajustando o regulador das lonas.', NULL, '["O tambor deve girar com leve arraste das lonas."]', '["Não deixe as lonas muito apertadas para não aquecer."]', '2026-06-13T11:49:09.905+00:00', '2026-06-13T11:49:09.905+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-rear-brake-drum-step-5', 'guide-rear-brake-drum', 5, 'Montagem e teste', 'Recoloque a roda, aperte as porcas no torque correto, ajuste o freio de mão e teste a frenagem.', NULL, '["Bombeie o pedal e acione o freio de mão para assentar as lonas."]', '["Teste a frenagem em baixa velocidade antes de rodar normalmente."]', '2026-06-13T11:49:09.936+00:00', '2026-06-13T11:49:09.936+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-handbrake-step-1', 'guide-handbrake', 1, 'Preparação', 'Eleve a traseira com segurança, apoie em cavaletes e libere totalmente a alavanca do freio de mão.', NULL, '["Conte quantos cliques a alavanca sobe atualmente."]', '["Apoie o veículo em cavaletes antes de trabalhar embaixo."]', '2026-06-13T11:49:10.013+00:00', '2026-06-13T11:49:10.013+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-handbrake-step-2', 'guide-handbrake', 2, 'Acesso ao regulador', 'Localize a porca de regulagem do cabo, geralmente sob o console ou no equalizador do cabo.', NULL, '["Remova a manopla ou console se necessário para acessar a regulagem."]', '[]', '2026-06-13T11:49:10.036+00:00', '2026-06-13T11:49:10.036+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-handbrake-step-3', 'guide-handbrake', 3, 'Ajuste da tensão', 'Aperte a porca de regulagem gradualmente até o freio atuar entre o 3º e o 5º clique da alavanca.', NULL, '["Gire as rodas traseiras para sentir o ponto de travamento."]', '["Não deixe o cabo tenso demais para não arrastar as lonas."]', '2026-06-13T11:49:10.057+00:00', '2026-06-13T11:49:10.057+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-handbrake-step-4', 'guide-handbrake', 4, 'Teste', 'Acione e libere o freio algumas vezes, confira o travamento e teste em uma leve rampa.', NULL, '["As rodas devem girar livremente com o freio liberado."]', '["Teste em rampa com o veículo seguro antes de confiar no ajuste."]', '2026-06-13T11:49:10.079+00:00', '2026-06-13T11:49:10.079+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-shock-absorbers-step-1', 'guide-shock-absorbers', 1, 'Elevação e desmontagem inicial', 'Eleve o veículo, remova a roda e acesse a fixação superior e inferior do amortecedor.', NULL, '["Borrife desengripante nos parafusos antes de soltar."]', '["Use cavaletes e siga procedimento seguro de suspensão."]', '2026-06-13T11:49:10.180+00:00', '2026-06-13T11:49:10.180+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-shock-absorbers-step-2', 'guide-shock-absorbers', 2, 'Retirada do conjunto', 'Solte as fixações e retire o amortecedor ou a coluna conforme o eixo trabalhado.', NULL, '["Fotografe a posição dos componentes antes de desmontar."]', '["Molas comprimidas exigem ferramenta apropriada."]', '2026-06-13T11:49:10.202+00:00', '2026-06-13T11:49:10.202+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-shock-absorbers-step-3', 'guide-shock-absorbers', 3, 'Montagem do componente novo', 'Monte o amortecedor novo com os acessórios em bom estado e recoloque no veículo.', NULL, '["Troque batentes e coifas desgastados no mesmo serviço."]', '["Não reutilize peças com folga ou dano visível."]', '2026-06-13T11:49:10.231+00:00', '2026-06-13T11:49:10.231+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-shock-absorbers-step-4', 'guide-shock-absorbers', 4, 'Aperto final e teste', 'Aperte as fixações com o veículo em posição correta, remonte a roda e faça teste em baixa velocidade.', NULL, '["Depois do serviço, providencie alinhamento da suspensão."]', '[]', '2026-06-13T11:49:10.252+00:00', '2026-06-13T11:49:10.252+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ball-joints-step-1', 'guide-ball-joints', 1, 'Acesso ao conjunto', 'Eleve o veículo, remova a roda e identifique o pivô ou articulação com folga.', NULL, '["Confirme a folga com inspeção física antes de desmontar."]', '["Apoie o veículo de forma segura em cavaletes."]', '2026-06-13T11:49:10.317+00:00', '2026-06-13T11:49:10.317+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ball-joints-step-2', 'guide-ball-joints', 2, 'Desacoplamento do componente', 'Solte os fixadores e utilize extrator para separar o pivô da manga de eixo ou bandeja.', NULL, '["Desengripante ajuda em componentes antigos."]', '["Não bata diretamente na rosca do pivô."]', '2026-06-13T11:49:10.339+00:00', '2026-06-13T11:49:10.339+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ball-joints-step-3', 'guide-ball-joints', 3, 'Instalação da peça nova', 'Posicione a nova articulação, reinstale os parafusos e faça o aperto conforme especificação.', NULL, '["Substitua travas e porcas autotravantes quando necessário."]', '["Aperto insuficiente compromete a segurança da suspensão."]', '2026-06-13T11:49:10.360+00:00', '2026-06-13T11:49:10.360+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-ball-joints-step-4', 'guide-ball-joints', 4, 'Validação final', 'Monte a roda, baixe o veículo e faça teste curto, seguido de alinhamento.', NULL, '["Verifique se não restou ruído ou folga após a troca."]', '[]', '2026-06-13T11:49:10.383+00:00', '2026-06-13T11:49:10.383+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cv-boot-step-1', 'guide-cv-boot', 1, 'Inspeção visual', 'Eleve o veículo e inspecione as coifas do homocinético dos dois lados. Procure por rachaduras, rasgos ou graxa espalhada nas rodas.', NULL, '["Gire o semi-eixo manualmente para inspecionar toda a extensão da coifa."]', '["Apoie o veículo em cavaletes antes de trabalhar sob ele."]', '2026-06-13T11:49:10.444+00:00', '2026-06-13T11:49:10.444+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cv-boot-step-2', 'guide-cv-boot', 2, 'Remoção da coifa danificada', 'Corte as abraçadeiras antigas com o alicate. Deslize a coifa danificada para fora do semi-eixo e remova a graxa velha.', NULL, '["Identifique se é a coifa do lado da roda ou do câmbio — os tamanhos são diferentes."]', '["Evite contaminar o homocinético com sujeira durante a remoção."]', '2026-06-13T11:49:10.470+00:00', '2026-06-13T11:49:10.470+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cv-boot-step-3', 'guide-cv-boot', 3, 'Instalação da coifa nova', 'Aplique toda a graxa do kit no homocinético, deslize a coifa nova no posicionamento correto e fixe as abraçadeiras novas.', NULL, '["Use toda a graxa que veio no kit — a quantidade é calibrada para o homocinético."]', '["Aperte as abraçadeiras com firmeza para evitar perda de graxa."]', '2026-06-13T11:49:10.491+00:00', '2026-06-13T11:49:10.491+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-cv-boot-step-4', 'guide-cv-boot', 4, 'Teste em rodagem', 'Abaixe o veículo, faça percurso curto executando curvas abertas e fechadas e escute se há ruído tipo clique.', NULL, '["Ruído de clique nas curvas pode indicar homocinético já danificado."]', '[]', '2026-06-13T11:49:10.512+00:00', '2026-06-13T11:49:10.512+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-power-steering-fluid-step-1', 'guide-power-steering-fluid', 1, 'Localização do reservatório', 'Abra o capô e localize o reservatório de fluido da direção hidráulica — frasco plástico translúcido com tampa marcada com símbolo de volante.', NULL, '["Verifique o nível com o motor frio para leitura precisa."]', '["Motor deve estar desligado e frio antes de abrir o reservatório."]', '2026-06-13T11:49:10.587+00:00', '2026-06-13T11:49:10.587+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-power-steering-fluid-step-2', 'guide-power-steering-fluid', 2, 'Remoção do fluido antigo', 'Com a seringa ou pera, aspire todo o fluido antigo do reservatório. Limpe o interior do reservatório com pano limpo.', NULL, '["Fluido escuro ou com cheiro queimado indica que a troca está atrasada."]', '["Descarte o fluido antigo corretamente — não jogue no esgoto."]', '2026-06-13T11:49:10.609+00:00', '2026-06-13T11:49:10.609+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-power-steering-fluid-step-3', 'guide-power-steering-fluid', 3, 'Abastecimento com fluido novo', 'Adicione fluido novo até o nível máximo indicado no reservatório usando um funil.', NULL, '["Não ultrapasse o nível máximo — excesso causa vazamento."]', '["Nunca misture fluidos de especificações diferentes."]', '2026-06-13T11:49:10.634+00:00', '2026-06-13T11:49:10.634+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-power-steering-fluid-step-4', 'guide-power-steering-fluid', 4, 'Sangria e verificação final', 'Ligue o motor e gire o volante de batente a batente 5 a 6 vezes para circular o fluido novo. Verifique o nível e complete se necessário.', NULL, '["Repita o giro do volante com o motor em marcha lenta.","Verifique se não há vazamentos ao redor do reservatório."]', '["Não mantenha o volante no batente por mais de 3 segundos seguidos para não danificar a bomba."]', '2026-06-13T11:49:10.660+00:00', '2026-06-13T11:49:10.660+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tie-rods-step-1', 'guide-tie-rods', 1, 'Preparação e remoção da roda', 'Eleve a dianteira com segurança, apoie em cavaletes e retire a roda do lado a ser trabalhado.', NULL, '["Marque a posição atual do terminal na barra para manter o alinhamento aproximado."]', '["Apoie o veículo em cavaletes antes de trabalhar."]', '2026-06-13T11:49:10.739+00:00', '2026-06-13T11:49:10.739+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tie-rods-step-2', 'guide-tie-rods', 2, 'Soltura do terminal', 'Solte a contraporca da barra axial e a porca do terminal na manga de eixo.', NULL, '["Conte as voltas ao desrosquear o terminal para reposicionar igual."]', '["Não danifique a coifa do terminal próximo."]', '2026-06-13T11:49:10.769+00:00', '2026-06-13T11:49:10.769+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tie-rods-step-3', 'guide-tie-rods', 3, 'Extração e substituição', 'Use o extrator para soltar o cone do terminal da manga, retire o terminal antigo e instale o novo.', NULL, '["Rosqueie o terminal novo o mesmo número de voltas do antigo."]', '["Não bata com martelo na manga para soltar o cone, use o extrator."]', '2026-06-13T11:49:10.792+00:00', '2026-06-13T11:49:10.792+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-tie-rods-step-4', 'guide-tie-rods', 4, 'Aperto e alinhamento', 'Aperte a porca do terminal e a contraporca no torque correto, recoloque a roda e procure um alinhamento.', NULL, '["Após a troca é obrigatório fazer alinhamento da direção."]', '["Não circule por muito tempo sem alinhar para não desgastar os pneus."]', '2026-06-13T11:49:10.815+00:00', '2026-06-13T11:49:10.815+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-stabilizer-bushings-step-1', 'guide-stabilizer-bushings', 1, 'Preparação', 'Eleve a dianteira com segurança, apoie em cavaletes e localize a barra estabilizadora e suas buchas.', NULL, '["Inspecione também as bieletas (links) da barra."]', '["Apoie o veículo em cavaletes antes de trabalhar embaixo."]', '2026-06-13T11:49:10.904+00:00', '2026-06-13T11:49:10.904+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-stabilizer-bushings-step-2', 'guide-stabilizer-bushings', 2, 'Remoção dos suportes', 'Solte os parafusos dos suportes (grampos) que prendem as buchas ao subchassi.', NULL, '["Fotografe a posição dos grampos antes de soltar."]', '["A barra pode descer levemente ao soltar os suportes."]', '2026-06-13T11:49:10.926+00:00', '2026-06-13T11:49:10.926+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-stabilizer-bushings-step-3', 'guide-stabilizer-bushings', 3, 'Substituição das buchas', 'Retire as buchas antigas, aplique graxa apropriada e instale as buchas novas na barra.', NULL, '["Posicione o corte da bucha conforme orientação original."]', '["Use graxa compatível com borracha para não deteriorar a bucha."]', '2026-06-13T11:49:10.947+00:00', '2026-06-13T11:49:10.947+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-stabilizer-bushings-step-4', 'guide-stabilizer-bushings', 4, 'Montagem e teste', 'Recoloque os suportes, aperte no torque correto, baixe o veículo e teste em via com ondulações.', NULL, '["Os ruídos de batida na dianteira devem cessar."]', '["Aperte os parafusos com o peso do carro no solo, se possível."]', '2026-06-13T11:49:10.975+00:00', '2026-06-13T11:49:10.975+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wheel-bearings-step-1', 'guide-wheel-bearings', 1, 'Remoção da roda e cubo', 'Eleve o veículo com segurança, retire a roda e o disco/tambor para acessar o cubo de roda.', NULL, '["Identifique o tipo de rolamento (cubo integrado ou prensado)."]', '["Apoie o veículo em cavaletes antes de trabalhar."]', '2026-06-13T11:49:11.060+00:00', '2026-06-13T11:49:11.060+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wheel-bearings-step-2', 'guide-wheel-bearings', 2, 'Desmontagem dos componentes', 'Solte a porca do cubo e remova os componentes necessários para liberar o conjunto do rolamento.', NULL, '["Fotografe a sequência de desmontagem."]', '["A porca do cubo tem alto torque; use ferramenta adequada."]', '2026-06-13T11:49:11.083+00:00', '2026-06-13T11:49:11.083+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wheel-bearings-step-3', 'guide-wheel-bearings', 3, 'Extração do rolamento antigo', 'Com a prensa ou sacador, extraia o rolamento antigo da manga de eixo ou do cubo.', NULL, '["Aquecer levemente o alojamento facilita a extração em alguns casos."]', '["Não danifique o alojamento da manga durante a extração."]', '2026-06-13T11:49:11.107+00:00', '2026-06-13T11:49:11.107+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wheel-bearings-step-4', 'guide-wheel-bearings', 4, 'Instalação do rolamento novo', 'Prense o rolamento novo no alojamento aplicando força apenas na pista externa e recoloque o anel de trava.', NULL, '["Aplique força na pista externa ao prensar para não danificar o rolamento."]', '["Prensar pela pista errada destrói o rolamento novo."]', '2026-06-13T11:49:11.133+00:00', '2026-06-13T11:49:11.133+00:00');
INSERT OR IGNORE INTO GuideStep (id, guideId, stepNumber, title, description, imageUrl, tips, warnings, createdAt, updatedAt) VALUES ('guide-wheel-bearings-step-5', 'guide-wheel-bearings', 5, 'Montagem e teste', 'Remonte o cubo, aperte a porca no torque correto, recoloque a roda e teste verificando ruídos e folga.', NULL, '["Gire a roda para confirmar giro suave e sem ruído."]', '["Respeite o torque da porca do cubo para não danificar o rolamento."]', '2026-06-13T11:49:11.153+00:00', '2026-06-13T11:49:11.153+00:00');
